_BOARD_STARTUP_ROOT = Path(__file__).resolve().parent

_ct_runtime_hotkey_source = '"""Read-only CE runtime hotkeys. No CT files, injection, hooks or UI messages.\n\nLayout is checked against the installed CE x64 build\'s live VMT metadata.\nDiscovery runs only in the isolated worker; cached records are sampled at 4 Hz.\n"""\nimport ctypes as C\nfrom ctypes import wintypes as W\nimport json\nimport struct\nimport time\n\nTARGET = \'GPT-6 NO GAME OVER - KEEP BLOOD EFFECT\'\nPOLL_SECONDS = .25\nK = C.WinDLL(\'kernel32\', use_last_error=True)\n\n\nclass ProcessEntry(C.Structure):\n    _fields_ = [(\'size\', W.DWORD), (\'usage\', W.DWORD), (\'pid\', W.DWORD),\n                (\'heap\', C.c_size_t), (\'module\', W.DWORD), (\'threads\', W.DWORD),\n                (\'parent\', W.DWORD), (\'priority\', W.LONG), (\'flags\', W.DWORD),\n                (\'name\', W.WCHAR * 260)]\n\n\nclass ModuleEntry(C.Structure):\n    _fields_ = [(\'size\', W.DWORD), (\'id\', W.DWORD), (\'pid\', W.DWORD),\n                (\'global_refs\', W.DWORD), (\'refs\', W.DWORD), (\'base\', C.c_void_p),\n                (\'image_size\', W.DWORD), (\'module\', W.HMODULE),\n                (\'name\', W.WCHAR * 256), (\'path\', W.WCHAR * 260)]\n\n\nclass MemoryInfo(C.Structure):\n    _fields_ = [(\'base\', C.c_void_p), (\'allocation\', C.c_void_p),\n                (\'allocation_protect\', W.DWORD), (\'size\', C.c_size_t),\n                (\'state\', W.DWORD), (\'protect\', W.DWORD), (\'kind\', W.DWORD)]\n\n\nfor name, args, result in (\n    (\'OpenProcess\', [W.DWORD, W.BOOL, W.DWORD], W.HANDLE),\n    (\'CloseHandle\', [W.HANDLE], W.BOOL),\n    (\'ReadProcessMemory\', [W.HANDLE, C.c_void_p, C.c_void_p, C.c_size_t, C.POINTER(C.c_size_t)], W.BOOL),\n    (\'VirtualQueryEx\', [W.HANDLE, C.c_void_p, C.POINTER(MemoryInfo), C.c_size_t], C.c_size_t),\n    (\'WaitForSingleObject\', [W.HANDLE, W.DWORD], W.DWORD),\n    (\'CreateToolhelp32Snapshot\', [W.DWORD, W.DWORD], W.HANDLE),\n    (\'Process32FirstW\', [W.HANDLE, C.POINTER(ProcessEntry)], W.BOOL),\n    (\'Process32NextW\', [W.HANDLE, C.POINTER(ProcessEntry)], W.BOOL),\n    (\'Module32FirstW\', [W.HANDLE, C.POINTER(ModuleEntry)], W.BOOL),\n    (\'Module32NextW\', [W.HANDLE, C.POINTER(ModuleEntry)], W.BOOL),\n):\n    f = getattr(K, name); f.argtypes = args; f.restype = result\n\n\ndef entries(flags, pid, cls, first, following):\n    handle = K.CreateToolhelp32Snapshot(flags, pid)\n    if handle == W.HANDLE(-1).value: raise C.WinError(C.get_last_error())\n    result = []\n    try:\n        row = cls(); row.size = C.sizeof(row)\n        ok = first(handle, C.byref(row))\n        while ok:\n            result.append(cls.from_buffer_copy(row))\n            ok = following(handle, C.byref(row))\n        if C.get_last_error() != 18: raise C.WinError(C.get_last_error())\n        return result\n    finally:\n        K.CloseHandle(handle)\n\n\ndef ce_pids():\n    return [p.pid for p in entries(2, 0, ProcessEntry, K.Process32FirstW, K.Process32NextW)\n            if p.name.lower().startswith(\'cheatengine\') and p.name.lower().endswith(\'.exe\')\n            and \'x86_64\' in p.name.lower()]\n\n\ndef q(raw, offset=0): return struct.unpack_from(\'<Q\', raw, offset)[0]\n\n\nclass Reader:\n    def __init__(self, pid):\n        self.pid = pid\n        self.handle = K.OpenProcess(0x100410, False, pid)  # QUERY | VM_READ | SYNCHRONIZE\n        if not self.handle: raise C.WinError(C.get_last_error())\n\n    def close(self):\n        if self.handle: K.CloseHandle(self.handle); self.handle = None\n\n    def alive(self): return bool(self.handle and K.WaitForSingleObject(self.handle, 0) == 258)\n\n    def read(self, address, size):\n        if not 0x10000 <= address < address + size < 0x800000000000 or not 0 < size <= 0x100000:\n            raise ValueError(\'Invalid CE read range\')\n        buf = C.create_string_buffer(size); got = C.c_size_t()\n        if not K.ReadProcessMemory(self.handle, address, buf, size, C.byref(got)) or got.value != size:\n            raise OSError(\'CE memory changed or became unreadable\')\n        return buf.raw\n\n    def u64(self, address): return q(self.read(address, 8))\n\n    def string(self, address):\n        head = self.read(address - 24, 24)\n        length = q(head, 16)\n        if not 0 < length <= 512: raise ValueError(\'Invalid CE description length\')\n        return self.read(address, length).decode(\'utf-8\', \'strict\')\n\n\n# FPC VMTs: (RVA, class name, instance size). Unknown builds fail visibly.\nPROFILE = {\n    \'record\': (0xBE4BD8, \'TMemoryRecord\', 0x1B8),\n    \'hotkey\': (0xBE4AE8, \'TMemoryRecordHotkey\', 0x70),\n    \'addresslist\': (0xBE2CF0, \'TAddresslist\', 0x6C8),\n    \'list\': (0xE456C0, \'TList\', 0x20),\n    \'fplist\': (0xE454F0, \'TFPList\', 0x18),\n    \'node\': (0xBE2158, \'TMemoryRecordTreeNode\', 0x98),\n}\n\n\nclass Session:\n    def __init__(self, pid):\n        self.memory = Reader(pid); self.pid = pid\n        self.records = set(); self.scanner = None; self.next_scan = 0.; self.failed_pages = 0\n        self.discovered = False\n        try:\n            modules = entries(8, pid, ModuleEntry, K.Module32FirstW, K.Module32NextW)\n            main = next(m for m in modules if m.name.lower().startswith(\'cheatengine\'))\n            self.base = int(main.base)\n            header = self.memory.read(self.base, 4096); pe = struct.unpack_from(\'<I\', header, 60)[0]\n            if (header[:2] != b\'MZ\' or header[pe:pe+4] != b\'PE\\0\\0\'\n                    or struct.unpack_from(\'<H\', header, pe+4)[0] != 0x8664\n                    or struct.unpack_from(\'<H\', header, pe+24)[0] != 0x20b):\n                raise ValueError(\'Unsupported CE runtime build\')\n            self.vmt = {}\n            for key, (rva, name, size) in PROFILE.items():\n                vmt = self.base + rva; data = self.memory.read(vmt, 32)\n                ptr = q(data, 24); label = name.encode(\'ascii\')\n                if q(data) != size or self.memory.read(ptr, len(label)+1) != bytes([len(label)])+label:\n                    raise ValueError(\'Unsupported CE object layout: \' + name)\n                self.vmt[key] = vmt\n        except BaseException:\n            self.close(); raise\n\n    def close(self): self.memory.close()\n\n    def record(self, address):\n        """Require a live record, address-list owner and tree-node backlink.\n\n        Description text identifies the feature only. It never supplies key codes.\n        Re-read both the record and hotkey lists to reject concurrent CE edits.\n        """\n        m = self.memory; raw = m.read(address, 0x1B8)\n        if q(raw) != self.vmt[\'record\']: raise ValueError(\'Record was removed\')\n        owner, desc, hotlist, node = (q(raw, off) for off in (0x50, 0x58, 0x70, 0x150))\n        if m.u64(owner) != self.vmt[\'addresslist\']: raise ValueError(\'Record owner changed\')\n        tree = m.read(node, 0x30)\n        if q(tree) != self.vmt[\'node\'] or q(tree, 0x28) != address:\n            raise ValueError(\'Record no longer belongs to the current tree\')\n        description = m.string(desc)\n        if not (description == TARGET or description.startswith(TARGET + \' -\')):\n            raise ValueError(\'Different record\')\n        outer = m.read(hotlist, 16)\n        if q(outer) != self.vmt[\'list\']: raise ValueError(\'Invalid hotkey list\')\n        inner_address = q(outer, 8); inner = m.read(inner_address, 24)\n        count, capacity = struct.unpack_from(\'<ii\', inner, 16)\n        if q(inner) != self.vmt[\'fplist\'] or not 0 <= count <= min(capacity, 64):\n            raise ValueError(\'Hotkey list is changing\')\n        items = m.read(q(inner, 8), count*8) if count else b\'\'\n        keys = []\n        for offset in range(0, len(items), 8):\n            pointer = q(items, offset); hotkey = m.read(pointer, 0x70)\n            if q(hotkey) != self.vmt[\'hotkey\'] or q(hotkey, 0x48) != address:\n                raise ValueError(\'Hotkey owner changed\')\n            combo = []\n            for code in struct.unpack_from(\'<5H\', hotkey, 0x5C):\n                if not code: break\n                combo.append(code)\n            if m.read(pointer, 0x70) != hotkey: raise ValueError(\'Hotkey is changing\')\n            keys.append(dict(keys=combo, active=bool(hotkey[0x6A]), action=hotkey[0x69]))\n        if (m.read(hotlist, 16) != outer or m.read(inner_address, 24) != inner\n                or (count and m.read(q(inner, 8), count*8) != items)):\n            raise ValueError(\'Hotkeys changed while reading\')\n        final = m.read(address, 0x1B8)\n        if any(raw[o:o+8] != final[o:o+8] for o in (0, 0x50, 0x58, 0x70, 0x150, 0x168)):\n            raise ValueError(\'Record identity changed while reading\')\n        if m.read(node, 0x30) != tree: raise ValueError(\'Tree changed while reading\')\n        return dict(pid=self.pid, record=hex(address), description=description,\n                    enabled=bool(final[0x19C]), hotkeys=keys)\n\n    def discover(self):\n        m = self.memory; cursor = 0x10000; needle = struct.pack(\'<Q\', self.vmt[\'record\'])\n        self.failed_pages = 0\n        while cursor < 0x800000000000:\n            info = MemoryInfo()\n            if not K.VirtualQueryEx(m.handle, cursor, C.byref(info), C.sizeof(info)): break\n            start = int(info.base or 0); end = start + info.size\n            if end <= cursor: break\n            cursor = end\n            if info.state != 0x1000 or info.kind != 0x20000 or info.protect & 0x101: continue\n            if info.protect & 0xFF not in (2, 4, 8, 32, 64, 128): continue\n            for pos in range(start, end, 0x100000):\n                try: data = m.read(pos, min(0x100000, end-pos))\n                except (ValueError, OSError): self.failed_pages += 1; yield None; continue\n                index = data.find(needle)\n                while index >= 0:\n                    address = pos + index\n                    if address % 8 == 0:\n                        try: self.record(address)\n                        except (OSError, ValueError): pass\n                        else: self.records.add(address)\n                    index = data.find(needle, index+8)\n                yield None\n\n    def tick(self):\n        now = time.monotonic()\n        if self.scanner is None and not self.records and now >= self.next_scan:\n            self.scanner = self.discover()\n        if self.scanner is not None:\n            deadline = now + .06\n            for _ in range(64):\n                try: next(self.scanner)\n                except StopIteration:\n                    self.scanner = None; self.next_scan = now + 3.; self.discovered = True; break\n                if time.monotonic() >= deadline: break\n        rows = []\n        for address in tuple(self.records):\n            try: rows.append(self.record(address))\n            except (OSError, ValueError):\n                self.records.discard(address); self.next_scan = 0.\n        return rows\n\n\ndef worker_main(parent_pid):\n    parent = K.OpenProcess(0x100000, False, int(parent_pid))\n    if not parent: return\n    sessions = {}; errors = {}; next_discovery = 0.; last = None; last_emit = 0.\n    try:\n        while K.WaitForSingleObject(parent, 0) == 258:\n            now = time.monotonic()\n            for pid, session in tuple(sessions.items()):\n                if not session.memory.alive():\n                    session.close(); del sessions[pid]; next_discovery = 0.\n            if now >= next_discovery:\n                next_discovery = now+2.\n                try:\n                    pids = ce_pids(); errors = {}\n                    for pid in pids:\n                        if pid not in sessions:\n                            try: sessions[pid] = Session(pid)\n                            except (OSError, ValueError, StopIteration) as exc: errors[pid] = str(exc)\n                    for pid in set(sessions)-set(pids): sessions.pop(pid).close()\n                except OSError as exc: errors = {0: str(exc)}\n            rows = []; scanning = False; partial = False\n            for pid, session in sessions.items():\n                try:\n                    rows.extend(session.tick()); scanning |= not session.discovered\n                    partial |= bool(session.failed_pages)\n                except (OSError, ValueError) as exc: errors[pid] = str(exc)\n            state = (\'ready\' if rows else \'error\' if errors else \'scanning\' if scanning\n                     else \'unreadable\' if partial else \'not_loaded\' if sessions else \'ce_closed\')\n            value = dict(state=state, records=sorted(rows, key=lambda r:(r[\'pid\'],r[\'record\'])), errors=errors)\n            signature = json.dumps(value, sort_keys=True, ensure_ascii=True)\n            if signature != last or now-last_emit >= 2.:\n                print(signature, flush=True); last = signature; last_emit = now\n            if K.WaitForSingleObject(parent, round(POLL_SECONDS*1000)) != 258: break\n    finally:\n        for session in sessions.values(): session.close()\n        K.CloseHandle(parent)\n'

if __name__=='__main__' and len(sys.argv)==3 and sys.argv[1]=='--ct-hotkey-worker':
    _ct_runtime_worker={'__name__':'ce_runtime_hotkey','__file__':__file__}
    exec(compile(_ct_runtime_hotkey_source,__file__+'::ce_runtime_hotkey','exec'),_ct_runtime_worker)
    raise SystemExit(_ct_runtime_worker['worker_main'](int(sys.argv[2])))

if __name__=='__main__' and len(sys.argv)==4 and sys.argv[1]=='--freecam-mouse-worker':
    _freecam_mouse_early_source = 'import ctypes as C\nfrom ctypes import wintypes as W\nimport mmap,os,struct,sys,time\nMAGIC=b\'RE6MSE01\'\nCAPTURE_CHANGED=0x8002\n"""Confine the active camera cursor to BH6\'s client area, on the input worker."""\nimport ctypes as C\nfrom ctypes import wintypes as W\n\n\ndef rect_tuple(rect):\n    return (rect.left,rect.top,rect.right,rect.bottom)\n\n\ndef intersection(a,b):\n    value=(max(a[0],b[0]),max(a[1],b[1]),min(a[2],b[2]),min(a[3],b[3]))\n    return value if value[0]<value[2] and value[1]<value[3] else None\n\n\nclass GUIThreadInfo(C.Structure):\n    _fields_=[(\'size\',W.DWORD),(\'flags\',W.DWORD),(\'active\',W.HWND),(\'focus\',W.HWND),\n              (\'capture\',W.HWND),(\'menu_owner\',W.HWND),(\'move_size\',W.HWND),\n              (\'caret\',W.HWND),(\'caret_rect\',W.RECT)]\n\n\nclass CursorMutex:\n    def __init__(self,kernel):\n        self.k=kernel\n        self.handle=kernel.CreateMutexW(None,False,\'Local\\\\GPT6_RE6_CameraCursor\')\n        if not self.handle:raise C.WinError(C.get_last_error())\n        self.held=False\n\n    def acquire(self):\n        if self.held:return True\n        result=self.k.WaitForSingleObject(self.handle,0)\n        if result in (0,0x80):self.held=True;return True\n        if result==258:return False\n        raise C.WinError(C.get_last_error())\n\n    def release(self):\n        if self.held:\n            if not self.k.ReleaseMutex(self.handle):raise C.WinError(C.get_last_error())\n            self.held=False\n\n    def close(self):\n        self.release()\n        if self.handle:self.k.CloseHandle(self.handle);self.handle=None\n\n\nclass CursorCapture:\n    def __init__(self,user,mutex):\n        self.u=user;self.mutex=mutex;self.hwnd=None;self.applied=None;self.previous=None\n        self.manual_release=False;self.click_pending=False;self.target_pid=0;self.last_client=None\n        self.was_background=False;self.active=False;self.reason=\'inactive\'\n\n    def unavailable(self,reason):\n        self.reason=reason\n        return None\n\n    def clip_rect(self):\n        value=W.RECT()\n        if not self.u.GetClipCursor(C.byref(value)):raise C.WinError(C.get_last_error())\n        return rect_tuple(value)\n\n    def desktop_rect(self):\n        x,y,w,h=(self.u.GetSystemMetrics(i) for i in (76,77,78,79))\n        return (x,y,x+w,y+h)\n\n    def client_rect(self,hwnd):\n        rect=W.RECT()\n        if not self.u.GetClientRect(hwnd,C.byref(rect)):return None\n        first,last=W.POINT(rect.left,rect.top),W.POINT(rect.right,rect.bottom)\n        if not self.u.ClientToScreen(hwnd,C.byref(first)) or not self.u.ClientToScreen(hwnd,C.byref(last)):return None\n        return intersection((first.x,first.y,last.x,last.y),self.desktop_rect())\n\n    def target(self,pid):\n        # Observe switch intent before foreground checks: Start/Win can close\n        # and briefly return foreground to BH6 before the target app activates.\n        win=any(self.u.GetAsyncKeyState(key)&0x8000 for key in (0x5b,0x5c))\n        alt=bool(self.u.GetAsyncKeyState(0x12)&0x8000)\n        if win or alt:\n            self.manual_release=True;self.click_pending=False\n            return self.unavailable(\'win_held\' if win else \'alt_held\')\n        hwnd=self.u.GetForegroundWindow()\n        if not hwnd or not pid:\n            self.manual_release=True;self.click_pending=False;self.was_background=True\n            return self.unavailable(\'background\')\n        owner=W.DWORD();thread=self.u.GetWindowThreadProcessId(hwnd,C.byref(owner))\n        if owner.value!=pid or self.u.IsIconic(hwnd) or not self.u.IsWindowVisible(hwnd):\n            self.manual_release=True;self.click_pending=False;self.was_background=True\n            return self.unavailable(\'background\')\n        info=GUIThreadInfo();info.size=C.sizeof(info)\n        if not self.u.GetGUIThreadInfo(thread,C.byref(info)):\n            return self.unavailable(\'client_unavailable\')\n        root=lambda h:(self.u.GetAncestor(h,2) or h) if h else None\n        if info.flags&0x1e:\n            self.manual_release=True;self.click_pending=False\n            return self.unavailable(\'window_menu\')\n        if root(info.active)!=root(hwnd) or root(info.focus)!=root(hwnd):\n            self.manual_release=True;self.click_pending=False\n            return self.unavailable(\'other_window\')\n        rect=self.client_rect(hwnd)\n        if not rect:return self.unavailable(\'client_unavailable\')\n        point=W.POINT()\n        if not self.u.GetCursorPos(C.byref(point)):return self.unavailable(\'cursor_unavailable\')\n        inside=rect[0]<=point.x<rect[2] and rect[1]<=point.y<rect[3]\n        hit=self.u.WindowFromPoint(point)\n        if not inside or root(hit)!=root(hwnd):\n            # Never use the game-window centre to justify taking a pointer\n            # which is over the desktop, Board, title bar, or another popup.\n            self.manual_release=True;self.click_pending=False\n            return self.unavailable(\'outside_client\' if not inside else \'other_window\')\n        down=bool(self.u.GetAsyncKeyState(1)&0x8000)\n        if self.manual_release:\n            if down:\n                self.click_pending=True\n                return self.unavailable(\'activation_click\')\n            if not self.click_pending:return self.unavailable(\'manual_release\')\n            self.manual_release=False;self.click_pending=False;self.was_background=False\n        if self.hwnd!=hwnd and down:return self.unavailable(\'activation_click\')\n        # Recheck after hit testing; the activation click can change the owner\n        # between the earlier queries. The native repair also checks foreground.\n        if self.u.GetForegroundWindow()!=hwnd:\n            self.manual_release=True;self.click_pending=False\n            return self.unavailable(\'background\')\n        self.last_client=rect\n        return hwnd,rect,True\n\n    def update(self,pid,active):\n        if pid!=self.target_pid:\n            self.manual_release=False;self.click_pending=False;self.target_pid=pid\n        self.active=bool(active)\n        self.reason=\'inactive\'\n        observed=self.target(pid)  # Observe Win/background even while camera input is paused.\n        target=observed if active else None\n        if target is None:self.release();return False\n        hwnd,rect,inside=target\n        if self.hwnd is not None and self.hwnd!=hwnd:self.release()\n        if not self.mutex.acquire():\n            self.reason=\'capture_busy\';return False\n        if self.target(pid)!=target:\n            self.release();return False\n        self.reason=\'captured\'\n        current=self.clip_rect()\n        if self.hwnd is None:\n            self.hwnd=hwnd;self.previous=current\n        if self.applied is not None and current!=self.applied:\n            # A native/foreign owner changed the clip. Never undo it at shutdown.\n            self.applied=None;self.previous=current\n        if self.applied is None and current==rect:\n            return inside  # Observe the native client clip without claiming ownership.\n        if current!=rect:\n            value=W.RECT(*rect)\n            if not self.u.ClipCursor(C.byref(value)):raise C.WinError(C.get_last_error())\n            self.applied=rect\n        return inside\n\n    def release(self):\n        try:\n            if self.applied is not None and self.clip_rect()==self.applied:\n                # A foreground change must not restore an old game rectangle on\n                # the desktop. Keep an existing native restriction only while\n                # it is still inside the same foreground game\'s current client.\n                restore=None\n                if not self.manual_release and self.u.GetForegroundWindow()==self.hwnd and self.previous:\n                    client=self.client_rect(self.hwnd)\n                    if client and intersection(self.previous,client)==self.previous:\n                        restore=W.RECT(*self.previous)\n                if not self.u.ClipCursor(C.byref(restore) if restore is not None else None):\n                    raise C.WinError(C.get_last_error())\n        finally:\n            self.applied=self.previous=None;self.hwnd=None\n            self.mutex.release()\n\n    def close(self):\n        try:self.release()\n        finally:self.mutex.close()\n\n\ndef configure_api(user,kernel):\n    for lib,name,args,result in (\n        (user,\'GetForegroundWindow\',[],W.HWND),\n        (user,\'GetWindowThreadProcessId\',[W.HWND,C.POINTER(W.DWORD)],W.DWORD),\n        (user,\'IsIconic\',[W.HWND],W.BOOL),(user,\'IsWindowVisible\',[W.HWND],W.BOOL),\n        (user,\'GetGUIThreadInfo\',[W.DWORD,C.POINTER(GUIThreadInfo)],W.BOOL),\n        (user,\'GetClientRect\',[W.HWND,C.POINTER(W.RECT)],W.BOOL),\n        (user,\'ClientToScreen\',[W.HWND,C.POINTER(W.POINT)],W.BOOL),\n        (user,\'GetCursorPos\',[C.POINTER(W.POINT)],W.BOOL),\n        (user,\'GetWindowRect\',[W.HWND,C.POINTER(W.RECT)],W.BOOL),\n        (user,\'WindowFromPoint\',[W.POINT],W.HWND),\n        (user,\'GetAncestor\',[W.HWND,W.UINT],W.HWND),\n        (user,\'GetAsyncKeyState\',[C.c_int],C.c_short),\n        (user,\'GetClipCursor\',[C.POINTER(W.RECT)],W.BOOL),\n        (user,\'ClipCursor\',[C.POINTER(W.RECT)],W.BOOL),\n        (user,\'GetSystemMetrics\',[C.c_int],C.c_int),\n        (user,\'PostMessageW\',[W.HWND,W.UINT,W.WPARAM,W.LPARAM],W.BOOL),\n        (kernel,\'CreateMutexW\',[C.c_void_p,W.BOOL,W.LPCWSTR],W.HANDLE),\n        (kernel,\'WaitForSingleObject\',[W.HANDLE,W.DWORD],W.DWORD),\n        (kernel,\'ReleaseMutex\',[W.HANDLE],W.BOOL),(kernel,\'CloseHandle\',[W.HANDLE],W.BOOL),\n    ):\n        f=getattr(lib,name);f.argtypes=args;f.restype=result\n\n\n"""Aligned scalar stores for the 64-bit Windows mouse shared-memory protocol.\n\nstruct.pack_into clears its destination before packing; a second process can\nobserve that zero. Never use it for a live flag, heartbeat or seqlock counter.\nPayload copies remain protected by the odd/even sequence.\n"""\nimport ctypes as C\n\n\ndef store_u32(memory, offset, value):\n    C.c_uint32.from_buffer(memory, offset).value = int(value) & 0xffffffff\n\n\ndef store_u64(memory, offset, value):\n    C.c_uint64.from_buffer(memory, offset).value = int(value) & 0xffffffffffffffff\n\n\ndef request_live(memory, parent_alive, now_ms, magic):\n    if not parent_alive or memory[:8] != magic:\n        return 0, False\n    pid = int.from_bytes(memory[12:16], \'little\')\n    active = int.from_bytes(memory[16:20], \'little\')\n    stamp = int.from_bytes(memory[48:56], \'little\')\n    # Sample AFTER reading the writer\'s stamp. Sampling first rejects a valid\n    # heartbeat published in between as a future timestamp and drops capture.\n    now = now_ms() if callable(now_ms) else now_ms\n    return pid, bool(pid and active and 0 <= now - stamp <= 500)\n\n"""Raw mouse decoding and shared diagnostics; no process or input side effects."""\nimport struct\n\nCAPTURE_REASONS = (\'inactive\', \'captured\', \'background\', \'alt_held\', \'window_menu\',\n                   \'client_unavailable\', \'cursor_unavailable\', \'outside_client\',\n                   \'activation_click\', \'manual_release\', \'capture_busy\', \'capture_error\', \'win_held\', \'other_window\')\n\n\nclass RawMotion:\n    def __init__(self):\n        self.absolute = {}\n\n    def reset(self):\n        self.absolute.clear()\n\n    def decode(self, raw, header_size, metrics):\n        if len(raw)<header_size+24 or struct.unpack_from(\'<I\',raw)[0]!=0:\n            return 0,0,0\n        flags=struct.unpack_from(\'<H\',raw,header_size)[0]\n        buttons,wheel=struct.unpack_from(\'<Hh\',raw,header_size+4)\n        x,y=struct.unpack_from(\'<2i\',raw,header_size+12)\n        # Relative counts are independent of ClipCursor. Absolute sources (RDP,\n        # tablets, some virtual mice) need a baseline per device and desktop.\n        if flags&1:\n            virtual=bool(flags&2)\n            width,height=(metrics(78),metrics(79)) if virtual else (metrics(0),metrics(1))\n            pointer_format=\'<Q\' if header_size==24 else \'<I\'\n            device=struct.unpack_from(pointer_format,raw,8)[0]\n            key=(device,virtual,width,height)\n            previous=self.absolute.get(key)\n            self.absolute[key]=(x,y)\n            x,y=(0,0) if previous is None else (\n                round((x-previous[0])*max(0,width-1)/65535),\n                round((y-previous[1])*max(0,height-1)/65535))\n        return x,y,wheel if buttons&0x400 else 0\n\ndef worker_main(name,parent_pid):\n    memory=mmap.mmap(-1,128,tagname=name)\n    if memory[:8]!=MAGIC or struct.unpack_from(\'<I\',memory,8)[0]!=int(parent_pid):memory.close();return\n    u=C.WinDLL(\'user32\',use_last_error=True);k=C.WinDLL(\'kernel32\',use_last_error=True)\n    # ClientToScreen and ClipCursor must use the same physical pixels.\n    try:\n        u.SetThreadDpiAwarenessContext.argtypes=[W.HANDLE]\n        u.SetThreadDpiAwarenessContext.restype=W.HANDLE\n        if not u.SetThreadDpiAwarenessContext(W.HANDLE(-4)):\n            u.SetThreadDpiAwarenessContext(W.HANDLE(-3))\n    except AttributeError:pass\n    configure_api(u,k)\n    FOCUS_PROC=C.WINFUNCTYPE(None,W.HANDLE,W.DWORD,W.HWND,C.c_long,C.c_long,W.DWORD,W.DWORD)\n    u.SetWinEventHook.argtypes=[W.DWORD,W.DWORD,W.HMODULE,FOCUS_PROC,W.DWORD,W.DWORD,W.DWORD]\n    u.SetWinEventHook.restype=W.HANDLE\n    u.UnhookWinEvent.argtypes=[W.HANDLE];u.UnhookWinEvent.restype=W.BOOL\n    k.OpenEventW.argtypes=[W.DWORD,W.BOOL,W.LPCWSTR];k.OpenEventW.restype=W.HANDLE\n    k.SetEvent.argtypes=[W.HANDLE];k.SetEvent.restype=W.BOOL\n    PROC=C.WINFUNCTYPE(C.c_ssize_t,W.HWND,W.UINT,W.WPARAM,W.LPARAM)\n    class WindowClass(C.Structure):\n        _fields_=[(\'style\',W.UINT),(\'proc\',PROC),(\'clsExtra\',C.c_int),(\'wndExtra\',C.c_int),\n                  (\'instance\',W.HINSTANCE),(\'icon\',W.HICON),(\'cursor\',W.HANDLE),(\'background\',W.HBRUSH),\n                  (\'menu\',W.LPCWSTR),(\'name\',W.LPCWSTR)]\n    class Device(C.Structure):\n        _fields_=[(\'page\',W.USHORT),(\'usage\',W.USHORT),(\'flags\',W.DWORD),(\'window\',W.HWND)]\n    class Header(C.Structure):\n        _fields_=[(\'kind\',W.DWORD),(\'size\',W.DWORD),(\'device\',W.HANDLE),(\'param\',W.WPARAM)]\n    for lib,fn,args,restype in (\n        (k,\'OpenProcess\',[W.DWORD,W.BOOL,W.DWORD],W.HANDLE),\n        (k,\'CloseHandle\',[W.HANDLE],W.BOOL),(k,\'WaitForSingleObject\',[W.HANDLE,W.DWORD],W.DWORD),\n        (k,\'GetModuleHandleW\',[W.LPCWSTR],W.HMODULE),\n        (u,\'RegisterClassW\',[C.POINTER(WindowClass)],W.ATOM),\n        (u,\'CreateWindowExW\',[W.DWORD,W.LPCWSTR,W.LPCWSTR,W.DWORD,C.c_int,C.c_int,C.c_int,C.c_int,W.HWND,W.HMENU,W.HINSTANCE,W.LPVOID],W.HWND),\n        (u,\'DefWindowProcW\',[W.HWND,W.UINT,W.WPARAM,W.LPARAM],C.c_ssize_t),\n        (u,\'RegisterRawInputDevices\',[C.POINTER(Device),W.UINT,W.UINT],W.BOOL),\n        (u,\'GetRawInputData\',[W.HANDLE,W.UINT,W.LPVOID,C.POINTER(W.UINT),W.UINT],W.UINT),\n        (u,\'GetMessageW\',[C.POINTER(W.MSG),W.HWND,W.UINT,W.UINT],C.c_int),\n        (u,\'DispatchMessageW\',[C.POINTER(W.MSG)],C.c_ssize_t),\n        (u,\'SetTimer\',[W.HWND,C.c_size_t,W.UINT,C.c_void_p],C.c_size_t),\n        (u,\'GetForegroundWindow\',[],W.HWND),\n        (u,\'GetWindowThreadProcessId\',[W.HWND,C.POINTER(W.DWORD)],W.DWORD),\n        (u,\'DestroyWindow\',[W.HWND],W.BOOL),(u,\'PostQuitMessage\',[C.c_int],None),\n        (u,\'UnregisterClassW\',[W.LPCWSTR,W.HINSTANCE],W.BOOL)):\n        f=getattr(lib,fn);f.argtypes=args;f.restype=restype\n    parent=k.OpenProcess(0x100000,False,parent_pid)\n    if not parent:memory.close();return\n    focus_event=k.OpenEventW(2,False,name+\'_focus\')\n    focus_hook=None\n    capture=CursorCapture(u,CursorMutex(k))\n    total=[0,0,0];sequence=0;hdrsize=C.sizeof(Header);motion=RawMotion()\n    capture_stamp=0;capture_request=None;capture_allowed=False\n    def sync_capture(force=False):\n        nonlocal capture_stamp,capture_request,capture_allowed\n        now=round(time.monotonic()*1000)\n        store_u64(memory,112,now)\n        alive=k.WaitForSingleObject(parent,0)==258\n        pid,active=request_live(memory,alive,lambda:round(time.monotonic()*1000),MAGIC)\n        request=(pid,active,u.GetForegroundWindow(),\n                 u.GetAsyncKeyState(0x12)&0x8000,u.GetAsyncKeyState(1)&0x8000,u.GetAsyncKeyState(0x5b)&0x8000,u.GetAsyncKeyState(0x5c)&0x8000)\n        if not force and now-capture_stamp<16 and request==capture_request:return capture_allowed\n        capture_stamp=now;capture_request=request\n        try:\n            allowed=capture.update(pid,active)\n            store_u32(memory,108,CAPTURE_REASONS.index(capture.reason))\n            store_u32(memory,72,int(capture.applied is not None))\n            store_u32(memory,76,0)\n        except OSError as exc:\n            try:capture.release()\n            except OSError:pass\n            store_u32(memory,72,0)\n            store_u32(memory,76,int(getattr(exc,\'winerror\',0) or 1))\n            allowed=False\n            store_u32(memory,108,CAPTURE_REASONS.index(\'capture_error\'))\n        if not alive or memory[:8]!=MAGIC:u.PostQuitMessage(0)\n        enabled=bool(active and allowed)\n        if enabled!=capture_allowed:\n            motion.reset()\n            store_u32(memory,80,int(enabled))\n            generation=(struct.unpack_from(\'<I\',memory,84)[0]+1)&0xffffffff\n            store_u32(memory,84,generation)\n            store_u64(memory,88,now if enabled else 0)\n            store_u64(memory,96,0)\n            if focus_event:k.SetEvent(focus_event)\n        capture_allowed=enabled\n        return capture_allowed\n    @FOCUS_PROC\n    def focus_changed(_hook,_event,_window,_object,_child,_thread,_stamp):\n        # Delivered in this input process: no Tk poll or Board GIL is needed.\n        try:sync_capture(True)\n        except Exception:pass  # The timer/Raw Input path remains the fallback.\n    @PROC\n    def window_proc(hwnd,msg,wp,lp):\n        nonlocal sequence\n        try:\n            if msg in (0x113,CAPTURE_CHANGED):\n                sync_capture(True);return 0\n            if msg==0xff:\n                if not sync_capture():return 0\n                size=W.UINT()\n                if u.GetRawInputData(W.HANDLE(lp),0x10000003,None,C.byref(size),hdrsize)==0xffffffff:return 0\n                if not hdrsize+24<=size.value<=4096:return 0\n                buffer=C.create_string_buffer(size.value)\n                if u.GetRawInputData(W.HANDLE(lp),0x10000003,buffer,C.byref(size),hdrsize)!=size.value:return 0\n                raw=buffer.raw\n                if struct.unpack_from(\'<I\',raw)[0]!=0:return 0\n                dx,dy,wheel=motion.decode(raw,hdrsize,u.GetSystemMetrics)\n                store_u64(memory,120,round(time.monotonic()*1000))\n                if (dx or dy) and not struct.unpack_from(\'<Q\',memory,96)[0]:\n                    store_u64(memory,96,round(time.monotonic()*1000))\n                total[0]+=dx;total[1]+=dy\n                total[2]+=wheel\n                sequence=(sequence+2)&0xfffffffe\n                store_u32(memory,20,sequence|1)\n                struct.pack_into(\'<2q\',memory,24,*total[:2])\n                store_u64(memory,56,total[2])\n                store_u32(memory,20,sequence)\n                return 0\n        except Exception:\n            store_u32(memory,40,2);u.PostQuitMessage(1);return 0\n        return u.DefWindowProcW(hwnd,msg,wp,lp)\n    instance=k.GetModuleHandleW(None);title=\'GPT6FreecamMouse_\'+str(os.getpid());hwnd=None\n    wc=WindowClass(0,window_proc,0,0,instance,None,None,None,None,title)\n    try:\n        if not u.RegisterClassW(C.byref(wc)):raise C.WinError(C.get_last_error())\n        hwnd=u.CreateWindowExW(0,title,title,0,0,0,0,0,W.HWND(-3),None,instance,None)\n        if not hwnd:raise C.WinError(C.get_last_error())\n        device=Device(1,2,0x100,hwnd)\n        if not u.RegisterRawInputDevices(C.byref(device),1,C.sizeof(device)):raise C.WinError(C.get_last_error())\n        store_u64(memory,64,int(hwnd))\n        if not u.SetTimer(hwnd,1,16,None):raise C.WinError(C.get_last_error())\n        # EVENT_SYSTEM_FOREGROUND, WINEVENT_OUTOFCONTEXT. Timer is a fallback.\n        focus_hook=u.SetWinEventHook(3,3,None,focus_changed,0,0,0)\n        store_u32(memory,104,int(bool(focus_hook)))\n        sync_capture()\n        store_u32(memory,40,1)\n        msg=W.MSG()\n        while u.GetMessageW(C.byref(msg),None,0,0)>0:u.DispatchMessageW(C.byref(msg))\n    finally:\n        if focus_hook:u.UnhookWinEvent(focus_hook)\n        if focus_event:k.CloseHandle(focus_event)\n        try:capture.close()\n        except OSError:pass\n        finally:\n            store_u64(memory,64,0)\n            store_u32(memory,72,0)\n        store_u32(memory,40,0)\n        if hwnd:u.DestroyWindow(hwnd)\n        u.UnregisterClassW(title,instance);k.CloseHandle(parent);memory.close()\n\nif __name__==\'__main__\':\n    worker_main(sys.argv[1],int(sys.argv[2]))\n'
    _freecam_mouse_early = {'__name__':'freecam_mouse_worker','__file__':__file__}
    exec(compile(_freecam_mouse_early_source,__file__+'::freecam_mouse','exec'),_freecam_mouse_early)
    raise SystemExit(_freecam_mouse_early['worker_main'](sys.argv[2],int(sys.argv[3])))

def _board_dependency_root():
    """Verify the bundled Keystone files and reuse or publish a complete cache."""
    import base64
    import io
    import struct
    import tempfile
    import zipfile
    import uuid
    import shutil
    if sys.platform != 'win32' or struct.calcsize('P') != 8:
        raise RuntimeError('This Board requires 64-bit Python for Windows.')
    tag = '6429602c002087ddb148'
    parent = Path(tempfile.gettempdir()) / 'GPT6-RE6-Board-Vendor'
    with zipfile.ZipFile(io.BytesIO(base64.b85decode(_BOARD_KEYSTONE_ARCHIVE))) as archive:
        files = [(item.filename, archive.read(item))
                 for item in archive.infolist() if not item.is_dir()]

    def complete(root):
        try:
            for name, expected in files:
                path = root / name
                if path.stat().st_size != len(expected) or path.read_bytes() != expected:
                    return False
            return True
        except OSError:
            return False

    parent.mkdir(parents=True, exist_ok=True)
    staging = None
    index = 0
    try:
        while True:
            target = parent / (tag if index == 0 else tag + '.' + str(index))
            if complete(target):
                break
            # Never overwrite or remove a cache whose DLL may be in use.
            if target.exists() or target.is_symlink():
                index += 1
                continue
            if staging is None:
                staging = parent / (tag + '.staging-' + uuid.uuid4().hex)
                staging.mkdir()
                for name, data in files:
                    path = staging / name
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_bytes(data)
                (staging / '.ready').write_text('ready', encoding='ascii')
                if not complete(staging):
                    raise RuntimeError('Keystone cache extraction failed verification.')
            try:
                staging.rename(target)
            except FileExistsError:
                # A concurrent start published first; verify its files next.
                continue
            staging = None
            break
    finally:
        if staging is not None:
            shutil.rmtree(staging, ignore_errors=True)
    # The marker is advisory: verified files also work if it was lost or is
    # read-only. File contents, not this marker, determine cache completeness.
    try:
        ready = target / '.ready'
        if not ready.is_file():
            ready.write_text('ready', encoding='ascii')
    except OSError:
        pass
    if str(target) not in sys.path:
        sys.path.insert(0, str(target))
    import keystone
    return target

