# The returned mask records actual native state 2, not submission.\n        return body+\'skip:;\'\n\n    def install_hold(self):\n        from board_animation_cg_reverse import install\n        try:install(self)\n        except Exception:\n            for h in reversed(list(self.hooks)):\n                h.free();self.hooks.remove(h)\n            raise\n\n    def start(self,restart=False,preserve_effects=False):\n        if self.actions is None:\n            from board_animation_actions import Actions\n            self.actions=Actions(self)\n        a=self.control[\'actor\'];action=self.m.u32(a+0xf58)\n        cameras=self.cameras()\n        if any(x[\'queued\'] for x in cameras):\n            if preserve_effects:self.restart_wait=True\n            return dict(already_active=True,waiting_native_end=self.restart_wait)\n        if restart and action==1:\n            # Camera 200 can finish before the 1706-frame USM actor. Complete\n            # the controller through its native exit action before re-entering.\n            body=self.guards(\'skip\')+f\'cmp dword ptr [{a+0xf58}],1;jne skip;\'\n            for x in cameras:\n                if self.m.u8(x[\'record\']+8):raise ValueError(\'演出镜头槽已被其它镜头使用。\')\n                body+=f\'cmp byte ptr [{x["record"]+8}],0;jne skip;\'\n            body+=f\'push 0;push -1;push 0;push 1;push 2;mov ecx,{a};mov eax,[ecx];call dword ptr [eax+0xb8];mov ecx,{a+0xf3c};call 0xcfe000;mov dword ptr [{{DATA}}+8],1;skip:;\'\n            result=self.command.run(body,[self.control]+self.rows)\n            if result[\'native_output\'][0]!=1:raise ValueError(\'原生演出收尾状态已改变。\')\n            action=self.m.u32(a+0xf58)\n        if action not in (0,2,3):raise ValueError(\'演出控制器未进入可触发状态。\')\n        if self.effects and not preserve_effects:self.effects.reset(8)\n        if self.hold:self.m.write(self.hold.data+0x70,bytes(4))\n        body=self.guards(\'skip\')+f\'cmp dword ptr [{a+0xf58}],{action};jne skip;push 40;mov ecx,{self.c["save"]};call 0x464a