    # while we read. Adopt only this SLOT\'s explicit-command destination.\n        if self.hook and self.hook.installed and self.m.alive():\n            for slot,g in self.groups.items():\n                if slot in skip_slots:continue\n                g[\'anchor\']=self.m.floats(self.d(slot)+0x20,8)\n\n    def capture_anchor(self,slot,label):\n        from board_animation_anchor import capture\n        return capture(self.groups[slot][\'rows\'][0][\'actor\'],self.d(slot),True,label)\n\n    def forward_parts(self,slot,clean,label=\'skip\'):\n        effect=self.effects.resume(slot) if self.effects else \'\'\n        return \'\',forward_channels(self.c,self.groups[slot],f\'forward_{slot}_{label}\',self.d(slot),clean,effect)\n\n    def resume_paused(self,slot,objects):\n        # Recover an orphaned clock without installing playback/FX hooks.\n        expected=ORIGINAL\n        if self.hook and self.hook.installed:\n            if self.m.read(self.hook.block,len(self.hook.code))!=self.hook.code:\n                raise RuntimeError(\'本模块暂停入口代码已变化，未覆盖。\')\n            expected=self.hook.patch\n        if self.m.read(SITE,len(expected))!=expected:\n            raise RuntimeError(\'暂停入口仍有拥有者，未覆盖其动画控制。\')\n        group=detect_paused(self.m,self.c,objects).get(slot)\n        if group is None:raise ValueError(\'该 SLOT 当前没有残留暂停。\')\n        guard=\'\'.join(f\'cmp byte ptr [{SITE+i}],{value};jne skip;\' for i,value in enumerate(expected))\n        body=guard+forward_channels(self.c,group,f\'resume_{slot}\')+\'mov dword ptr [{DATA}+8],1;skip:;\'\n        result=self.command.run(body)\n        if result[\'native_output\'][0]!=1 or not result[\'native_output\'][1]&1:raise ValueError(\'玩家动作已改变，残留暂停未恢复。\')\n        return dict(command=result,message=f\'SLOT {slot} 已恢复原生速度；子体归宿不阻塞恢复。\')\n\n    def apply_options(self,slot,options):\n        if slot not in self.groups:raise ValueError(\'该 SLOT 当前没有完整的 EM4700 配对动画。\')\n        clean={k:bool(options.get(k,False)) for k in (\'loop\',\'