_EMBEDDED_SOURCES['board_privacy'] = '"""Pure output sanitizers; never inspect files, environment, or process data."""\nfrom pathlib import PurePath\nimport re\n\nREDACTED = \'[REDACTED]\'\nLOCAL_PATH = \'[LOCAL_PATH]\'\n_PRIVATE_NAMES = frozenset({\n    \'password\', \'passwd\', \'pwd\', \'secret\', \'clientsecret\', \'apikey\',\n    \'accesskey\', \'accesskeyid\', \'secretaccesskey\', \'accesstoken\',\n    \'authtoken\', \'refreshtoken\', \'authorization\', \'privatekey\',\n    \'credential\', \'credentials\', \'cookie\', \'cookies\', \'setcookie\',\n    \'account\', \'accountid\', \'accountname\', \'username\', \'useremail\',\n    \'email\', \'emailaddress\', \'login\', \'loginname\', \'steamid\', \'steamid64\',\n    \'broadcast\', \'broadcastcontent\', \'broadcastmessage\', \'broadcasttext\',\n    \'broadcastmessages\', \'broadcastpayload\', \'broadcastbody\',\n})\n_PATH = re.compile(\n    r\'\'\'(?ix)\n    (?:file:///?(?=[a-z]:[\\\\/]|/|[^\\s/]+/)[^\\r\\n\\x00<>|"\']+)\n    |(?:(?<![a-z0-9_])[a-z]:[\\\\/][^\\r\\n\\x00<>|"\']*)\n    |(?:\\\\\\\\(?:\\?\\\\|\\.\\\\)?[^\\s\\\\/<>|"\']+[\\\\/][^\\r\\n\\x00<>|"\']+)\n    |(?:(?<![a-z0-9_:/])/(?:(?:Users|home|root|tmp|private|var|opt|mnt|Volumes)/)[^\\r\\n\\x00<>|"\']*)\n    \'\'\'\n)\n_CREDENTIAL_URL = re.compile(r\'(?i)(\\b(?:https?|ftp)://)[^\\s/@:]+:[^\\s/@]+@\')\n_BEARER = re.compile(r\'(?i)\\bBearer\\s+[A-Za-z0-9._~+/=-]+\')\n_EMAIL = re.compile(r\'\\b[A-Za-z0-9.!#$%&*+/=?^_`{|}~-]+@[A-Za-z0-9-]+(?:\\.[A-Za-z0-9-]+)+\\b\')\n_PRIVATE_BLOCK = re.compile(r\'-----BEGIN (?:[A-Z ]+ )?PRIVATE KEY-----.*?-----END (?:[A-Z ]+ )?PRIVATE KEY-----\', re.S)\n_KNOWN_TOKEN = re.compile(r\'\\b(?:AKIA[A-Z0-9]{16}|ASIA[A-Z0-9]{16}|gh[pousr]_[A-Za-z0-9]{25,}|github_pat_[A-Za-z0-9_]{30,}|sk-(?:proj-)?[A-Za-z0-9_-]{32,}|xox[baprs]-[A-Za-z0-9-]{20,})\\b\')\n_ASSIGNMENT = re.compile(\n    r\'\'\'(?ix)(\\b(?:password|passwd|pwd|secret|client[_-]?secret|api[_-]?key|\n    access[_-]?token|auth[_-]?token|refresh[_-]?token|authorization|\n    account(?:[_-]?(?:id|name))?|username|login|broadcast(?:[_-]?(?:content|message|text|payload|body))?)\n    \\s*[=:]\\s*)(?:"[^"\\r\\n]*"|\'[^\'\\r\\n]*\'|[^\\s,;\\r\\n]+)\'\'\'\n)\n\n\ndef is_private_key(key):\n    if type(key) is not str:\n        return False\n    name = re.sub(r\'[^a-z0-9]\', \'\', key[:256].casefold())\n    return (name in _PRIVATE_NAMES or name.startswith((\'password\', \'passwd\', \'broadcast\'))\n            or name.endswith((\'password\', \'passwd\', \'apikey\', \'clientsecret\', \'accesstoken\', \'refreshtoken\')))\n\n\ndef redact_text(value):\n    """Redact recognizable paths/credentials, not arbitrary natural-language PII."""\n    value = _PRIVATE_BLOCK.sub(REDACTED, value)\n    value = _CREDENTIAL_URL.sub(lambda m: m[1] + REDACTED + \'@\', value)\n    value = _BEARER.sub(\'Bearer \' + REDACTED, value)\n    value = _KNOWN_TOKEN.sub(REDACTED, value)\n    value = _EMAIL.sub(REDACTED, value)\n    value = _ASSIGNMENT.sub(lambda m: m[1] + REDACTED, value)\n    return _PATH.sub(LOCAL_PATH, value)\n\n\ndef sanitize_report(value):\n    """Return a detached JSON-safe copy; never change operational input values."""\n    active = set()\n    remaining = [100000]\n\n    def walk(item, depth):\n        remaining[0] -= 1\n        if remaining[0] < 0 or depth > 32:\n            return \'[REPORT_LIMIT]\'\n        kind = type(item)\n        if item is None or kind in (bool, int, float):\n            return item\n        if kind is str:\n            return redact_text(item)\n        if isinstance(item, PurePath):\n            return redact_text(str(item))\n        if kind not in (dict, list, tuple):\n            return \'[UNSUPPORTED_VALUE]\'\n        identity = id(item)\n        if identity in active:\n            return \'[CYCLIC_REFERENCE]\'\n        active.add(identity)\n        try:\n            if kind is dict:\n                result = {}\n                for key, child in item.items():\n                    if remaining[0] <= 0:\n                        result[\'[REPORT_LIMIT]\'] = \'[REPORT_LIMIT]\'\n                        break\n                    private = is_private_key(key)\n                    safe_key = redact_text(key) if type(key) is str else str(key) if type(key) in (int, float, bool) or key is None else \'[KEY]\'\n                    base, suffix = safe_key, 1\n                    while safe_key in result:\n                        suffix += 1\n                        safe_key = base + \'#\' + str(suffix)\n                    result[safe_key] = REDACTED if private else walk(child, depth + 1)\n                return result\n            result = []\n            for child in item:\n                if remaining[0] <= 0:\n                    result.append(\'[REPORT_LIMIT]\')\n                    break\n                result.append(walk(child, depth + 1))\n            return result\n        finally:\n            active.remove(identity)\n\n    return walk(value, 0)\n'

_EMBEDDED_SOURCES['board_ui_input'] = '"""Require an explicit click before a value control accepts wheel input."""\nimport tkinter as tk\nfrom tkinter import ttk\nimport weakref\n\n_original_init = tk.BaseWidget.__init__\n_installed = False\n\n\nclass ClickWheelGuard:\n    def __init__(self, root):\n        self.root = root\n        self.active = None\n        self.tag = \'BoardClickWheel_\' + str(id(self))\n        root.bind_class(self.tag, \'<ButtonPress-1>\', self.clicked)\n        root.bind_class(self.tag, \'<FocusOut>\', self.released)\n        root.bind_class(self.tag, \'<Leave>\', self.released)\n        root.bind_class(self.tag, \'<Destroy>\', self.released)\n        for sequence in (\'<MouseWheel>\', \'<Button-4>\', \'<Button-5>\'):\n            root.bind_class(self.tag, sequence, self.wheel)\n\n    @staticmethod\n    def protected(widget):\n        return (isinstance(widget, (ttk.Combobox, ttk.Spinbox, tk.Spinbox, ttk.Scale, tk.Scale))\n                or isinstance(widget, tk.Canvas) and type(widget).__module__ == \'board_game_speed\')\n\n    def attach(self, widget):\n        tags = widget.bindtags()\n        if self.tag not in tags:\n            widget.bindtags((self.tag,) + tags)\n\n    def clicked(self, event):\n        widget = event.widget\n        self.active = weakref.ref(widget) if self.protected(widget) else None\n        if self.active:\n            widget.focus_set()\n\n    def released(self, event):\n        if self.active and self.active() is event.widget:\n            self.active = None\n\n    def wheel(self, event):\n        widget = event.widget\n        if not self.protected(widget):\n            return None\n        if self.active and self.active() is widget and widget.focus_get() is widget:\n            return None\n        # Forward once to the enclosing scroll area, bypassing value bindings.\n        parent = widget.master\n        if parent is not None:\n            try:\n                if event.num in (4, 5):\n                    parent.event_generate(\'<Button-%d>\' % event.num, state=event.state)\n                else:\n                    parent.event_generate(\'<MouseWheel>\', delta=event.delta, state=event.state)\n            except tk.TclError:\n                pass\n        return \'break\'\n\n\ndef _widget_init(widget, *args, **kwargs):\n    _original_init(widget, *args, **kwargs)\n    guard = getattr(widget._root(), \'_board_click_wheel\', None)\n    if guard:\n        guard.attach(widget)\n\n\ndef install(app):\n    global _installed\n    guard = getattr(app.root, \'_board_click_wheel\', None)\n    if guard is None:\n        guard = app.root._board_click_wheel = ClickWheelGuard(app.root)\n        pending = [app.root]\n        while pending:\n            widget = pending.pop()\n            guard.attach(widget)\n            pending.extend(widget.winfo_children())\n    if not _installed:\n        tk.BaseWidget.__init__ = _widget_init\n        _installed = True\n    return guard\n'
_EMBEDDED_SOURCES['board_control_release'] = '"""Explicit control intent and retryable release; no game discovery on import."""\n\n\ndef publish_intent(options):\n    app = options.app\n    revision = getattr(app, \'_slot_control_policy_request\', (0, False))[0] + 1\n    enabled = bool(options.choices.get(\'control\', False)) and not options.closed\n    app._slot_control_policy_request = (revision, enabled)\n    if enabled:\n        return\n    options._owner_sync.manual = None\n    options._control_applied_request = None\n    options._manual_owner_slot = None\n    options._manual_owner_ready = True\n    options._manual_released_slots = set()\n    options._native_resume_slot = None\n    options._native_resume_proof = None\n    options._native_control_follow = True\n    pending = getattr(options, \'slot_pending\', None)\n    if pending:\n        pending[\'superseded\'] = True\n        pending[\'cancel\'].set()\n    publish_formation = getattr(options, \'_publish_formation\', None)\n    if publish_formation:\n        publish_formation()\n\n\ndef release_local(options, sessions, recovery, release_observed, retry=None):\n    """Keep failed owners reachable so the worker retries their cleanup."""\n    errors = []\n    from board_hunt_input import close_shared_sessions\n    try:\n        close_shared_sessions()\n    except Exception as exc:\n        errors.append(str(exc))\n    try:\n        recovery.release_control()\n    except Exception as exc:\n        errors.append(str(exc))\n    session = sessions.get(\'control\')\n    if session is not None:\n        try:\n            release_observed(options, session)\n            session.close()\n        except Exception as exc:\n            errors.append(str(exc))\n        else:\n            sessions[\'control\'] = None\n    if retry is not None:\n        try:\n            retry.close()\n        except Exception as exc:\n            errors.append(str(exc))\n    if errors:\n        raise RuntimeError(\'Player control release pending: \' + \'; \'.join(errors))\n    return None\n\n\ndef report_release(options):\n    """A checkbox value alone is not proof that all background owners left."""\n    revision, enabled = getattr(options.app, \'_slot_control_policy_request\', (-1, False))\n    if enabled or revision < 0:\n        return\n    local = getattr(options.app, \'_control_release_local\', None)\n    child = getattr(options.app, \'_slot_control_policy_receipt\', {})\n    local_ready = bool(local and local[:2] == (revision, None))\n    child_ready = bool(child.get(\'revision\') == revision and child.get(\'enabled\') is False\n                       and child.get(\'released\') is True and not child.get(\'error\'))\n    formation = getattr(options, \'formation_service\', None)\n    formation_ready = (formation is None or (getattr(formation, \'guard\', None) is None and not formation.request[0]\n                       and formation.applied_request == formation.request))\n    trainer = getattr(options, \'trainer_slot_guard\', None)\n    trainer_ready = trainer is None or (trainer.status == \'disabled\' and trainer.guard is None)\n    ready = local_ready and child_ready and formation_ready and trainer_ready\n    error = (local[1] if local and local[0] == revision else None)\n    if child.get(\'revision\') == revision:\n        error = error or child.get(\'error\')\n    signature = (revision, ready, error)\n    if getattr(options, \'_last_control_release_status\', None) == signature:\n        return\n    options._last_control_release_status = signature\n    if ready:\n        text = \'强制控制已关闭；全部角色控制钩子和队形锁定已释放。\'\n    elif error:\n        text = \'角色控制释放尚未完成：\' + str(error)\n    else:\n        text = \'正在释放角色控制，等待后台释放回执。\'\n    options.app.messages.put((\'player_action\', text))\n\n\nclass WorkerControlPolicy:\n    """IPC intent is monotonic; only the command thread performs cleanup."""\n    def __init__(self):\n        self.request = (-1, False)\n        self.applied = None\n        self.last_error = None\n\n    def update(self, revision, enabled):\n        if type(revision) is not int or revision < 0 or type(enabled) is not bool:\n            raise ValueError(\'Invalid SLOT control policy.\')\n        if revision <= self.request[0]:\n            return False\n        self.request = (revision, enabled)\n        return True\n\n    def apply(self, close_pending, close_guards, send):\n        request = self.request\n        if request == self.applied:\n            return\n        revision, enabled = request\n        try:\n            if not enabled:\n                close_pending()\n                close_guards()\n        except Exception as exc:\n            signature = (revision, str(exc))\n            if signature != self.last_error:\n                send(dict(type=\'slot_control_policy\', revision=revision, enabled=enabled,\n                          released=False, error=str(exc)))\n                self.last_error = signature\n            return\n        self.applied = request\n        self.last_error = None\n        send(dict(type=\'slot_control_policy\', revision=revision, enabled=enabled,\n                  released=not enabled, error=None))\n'
class _EmbeddedLoader(importlib.abc.Loader):

    def __init__(self, name, source):
        self.name, self.source = (name, source)

    def create_module(self, spec):
        return None

    def _resolve_source(self):
        return _EMBEDDED_SOURCES[self.name]

    def exec_module(self, module):
        module.__file__ = str(BOARD_LOG_ROOT / (self.name + '.py'))
        presence = globals().get('_BOARD_PRESENCE_ENABLED', False)
        if presence:
            module.HUMAN_PRESENCE = HUMAN_PRESENCE
        self.source = self._resolve_source()
        exec(compile(self.source, module.__file__, 'exec'), module.__dict__)
        if presence:
            _human_presence_backend.install_consumer(module)
class _EmbeddedFinder(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        source = _EMBEDDED_SOURCES.get(fullname)
        if source is None:
            return None
        return importlib.util.spec_from_loader(
            fullname, _EmbeddedLoader(fullname, source),
            is_package=fullname in ('state', 'features', 'transport'))

