class BoardMenuButton(ttk.Menubutton):
    """Render menu entries with ttk: Windows native menus ignore dark colors."""
    def __init__(self,master=None,**kwargs):
        self._menu=None;self._dropdown_popup=None;self._outside_binding=None
        menu=kwargs.pop('menu',None)
        text=str(kwargs.get('text','')).replace('\u25be','').replace('\u25bc','').strip()
        kwargs['text']=text
        if not text:kwargs.update(style='Dropdown.TMenubutton',width=0)
        super().__init__(master,**kwargs)
        # Keep the themed arrow, but do not post a Windows native menu.
        self.bindtags(tuple(tag for tag in self.bindtags() if tag!='TMenubutton'))
        def activate(_event=None):
            self.open_dropdown();return 'break'
        for event in ('<ButtonPress-1>','<space>','<Return>','<Down>'):
            self.bind(event,activate)
        self.bind('<Enter>',lambda _e:self.state(['active']))
        self.bind('<Leave>',lambda _e:self.state(['!active']))
        if menu is not None:self.configure(menu=menu)
        self.bind('<Destroy>',lambda e:self.close_dropdown() if e.widget is self else None,add='+')

    def configure(self,cnf=None,**kwargs):
        if cnf is not None and isinstance(cnf,dict):kwargs={**cnf,**kwargs};cnf=None
        if 'menu' in kwargs:self._menu=kwargs.pop('menu')
        if 'text' in kwargs:
            kwargs['text']=str(kwargs['text']).replace('\u25be','').replace('\u25bc','').strip()
        return super().configure(cnf,**kwargs)

    config=configure

    def close_dropdown(self):
        root=self._root()
        if self._outside_binding is not None:
            try:root.unbind('<ButtonPress-1>',self._outside_binding)
            except tk.TclError:pass
            self._outside_binding=None
        popup=self._dropdown_popup;self._dropdown_popup=None
        if popup is not None:
            try:popup.destroy()
            except tk.TclError:pass

    def open_dropdown(self):
        if self._dropdown_popup is not None:
            self.close_dropdown();return
        if self.instate(['disabled']) or self._menu is None:return
        menu=self._menu if isinstance(self._menu,tk.Menu) else self.nametowidget(self._menu)
        last=menu.index('end')
        if last is None:return
        root=self._root();parent=getattr(self,'_parent_dropdown',None)
        if parent is None:
            previous=getattr(root,'_active_board_dropdown',None)
            if previous is not None and previous is not self:previous.close_dropdown()
            root._active_board_dropdown=self
        popup=tk.Toplevel(self.winfo_toplevel());popup.withdraw()
        self._dropdown_popup=popup
        popup.transient(self.winfo_toplevel());popup.overrideredirect(True);popup.attributes('-topmost',True)
        style=ttk.Style(self);bg=style.lookup('TFrame','background');border=style.lookup('TButton','bordercolor')
        from board_popup_layout import work_area,widget_rect,fit_popup
        anchor=getattr(self,'_popup_anchor',self) if parent is None else self.master
        area=work_area(anchor)
        left,top,right,bottom=area
        available_width=max(1,right-left);available_height=max(1,bottom-top)
        preferred_width=max(0,int(getattr(menu,'_board_preferred_width',0)))
        menu._board_content_width=min(available_width,preferred_width) if preferred_width else available_width
        shell=tk.Frame(popup,background=bg,highlightbackground=border,highlightthickness=1)
        shell.pack(fill='both',expand=True)
        viewport=tk.Canvas(shell,background=bg,highlightthickness=0,borderwidth=0)
        viewport.pack(side='left',fill='both',expand=True)
        scrollbar=ttk.Scrollbar(shell,orient='vertical',command=viewport.yview)
        viewport.configure(yscrollcommand=scrollbar.set)
        body=tk.Frame(viewport,background=bg,padx=5,pady=5)
        content=viewport.create_window(0,0,window=body,anchor='nw')
        if preferred_width:viewport.itemconfigure(content,width=max(1,menu._board_content_width-2))
        controls=[]
        menu._board_control_refs={}
        inline_checks=getattr(menu,'_board_inline_checks',{})
        skip_indices=set(inline_checks.values())
        wrap_groups=[]
        def choose(index,toggled=False):
            try:
                if toggled:
                    command=menu.entrycget(index,'command')
                    if command:self.tk.call('eval',command)
                else:menu.invoke(index)
            finally:
                # Checkboxes stay open so independent options can be combined.
                if menu.type(index)!='checkbutton' and not getattr(menu,'_board_keep_open',False):
                    self.close_dropdown()
        for index in range(last+1):
            if index in skip_indices: continue
            kind=menu.type(index)
            if kind=='separator':ttk.Separator(body).pack(fill='x',pady=4);continue
            label=menu.entrycget(index,'label')
            custom_row=getattr(menu,'_board_custom_rows',{}).get(index)
            if custom_row is not None:
                control=custom_row(body)
                menu._board_control_refs[index]=control;controls.append(control)
                continue
            inline_entry=getattr(menu,'_board_inline_entries',{}).get(index)
            if inline_entry is not None:
                row=ttk.Frame(body);row.pack(fill='x',anchor='w',pady=2)
                ttk.Label(row,text=label).pack(side='left')
                control=ttk.Entry(row,textvariable=inline_entry['variable'],width=8)
                control.pack(side='left',padx=4)
                # An override-redirect popup on Windows may receive a
                # mouse click without acquiring keyboard focus. Explicit
                # entry clicks must activate the editor before class bindings.
                control.bind('<ButtonPress-1>',lambda _e,entry=control:entry.focus_force(),add='+')
                def select_all(_event,entry=control):
                    entry.selection_range(0,'end');entry.icursor('end');return 'break'
                control.bind('<Control-a>',select_all)
                control.bind('<Control-A>',select_all)
                ttk.Label(row,text=inline_entry['unit']).pack(side='left')
                for event in ('<FocusOut>','<Return>'):
                    control.bind(event,lambda _e,commit=inline_entry['commit']:commit(),add='+')
                menu._board_control_refs[index]=control;controls.append(control)
                continue
            wrap=getattr(menu,'_board_wrap_groups',{}).get(index)
            if wrap:
                row=tk.Frame(body,background=bg)
                row.pack(fill='x',anchor='w',pady=2)
                row_controls=[]
                for wi in wrap:
                    wlabel=menu.entrycget(wi,'label')
                    wc=ttk.Checkbutton(row,text=wlabel,variable=menu.entrycget(wi,'variable'),
                                       onvalue=menu.entrycget(wi,'onvalue'),offvalue=menu.entrycget(wi,'offvalue'),
                                       command=lambda i=wi:choose(i,True))
                    if menu.entrycget(wi,'state')=='disabled':wc.state(['disabled'])
                    row_controls.append(wc);controls.append(wc)
                    skip_indices.add(wi)
                wrap_groups.append((row,row_controls))
                continue
            if index in getattr(menu,'_board_labels',set()):
                control=ttk.Label(body,text=label,anchor='w')
                from tkinter import font
                label_font=font.nametofont('TkDefaultFont',root).copy()
                size=label_font.cget('size')
                label_font.configure(size=max(7,size-1) if size>0 else min(-9,size+1))
                control.configure(font=label_font);control._menu_label_font=label_font
                control.pack(fill='x',anchor='w',pady=(3,1))
                controls.append(control)
                continue
            submenu=getattr(menu,'_board_submenus',{}).get(index)
            inline_index=inline_checks.get(index)
            entry=ttk.Frame(body) if submenu is not None or inline_index is not None else body
            if kind in ('checkbutton','radiobutton'):
                options=dict(text=label,variable=menu.entrycget(index,'variable'),
                             command=lambda i=index:choose(i,True))
                if kind=='checkbutton':
                    options.update(onvalue=menu.entrycget(index,'onvalue'),offvalue=menu.entrycget(index,'offvalue'))
                    control=ttk.Checkbutton(entry,**options)
                else:
                    control=ttk.Radiobutton(entry,value=menu.entrycget(index,'value'),**options)
            else:control=ttk.Button(entry,text=label,command=lambda i=index:choose(i),style='MenuItem.TButton')
            if menu.entrycget(index,'state')=='disabled':control.state(['disabled'])
            menu._board_control_refs[index]=control
            if inline_index is not None:
                entry.pack(fill='x',anchor='w',pady=2)
                control.pack(side='left',fill='x',expand=True)
                check=ttk.Checkbutton(entry,text=menu.entrycget(inline_index,'label'),
                    variable=menu.entrycget(inline_index,'variable'),
                    onvalue=menu.entrycget(inline_index,'onvalue'),offvalue=menu.entrycget(inline_index,'offvalue'),
                    command=lambda i=inline_index:choose(i,True))
                check.pack(side='right',padx=(8,0))
                if menu.entrycget(inline_index,'state')=='disabled':check.state(['disabled'])
                menu._board_control_refs[inline_index]=check
                controls.append(check)
            elif submenu is not None:
                entry.pack(fill='x',anchor='w',pady=2)
                control.pack(side='left',fill='x',expand=True)
                arrow=BoardMenuButton(entry,text='',menu=submenu)
                arrow._parent_dropdown=self
                arrow.pack(side='right',fill='y')
                def hover(_event=None,arrow=arrow):
                    if arrow._dropdown_popup is None:arrow.open_dropdown()
                for widget in (entry,control,arrow):widget.bind('<Enter>',hover,add='+')
            else:control.pack(fill='x',anchor='w',pady=2)
            controls.append(control)
            bind_entry_tooltip=getattr(self,'_bind_entry_tooltip',None)
            if bind_entry_tooltip:bind_entry_tooltip(index,control)
        popup.update_idletasks()
        desired_width=max(self.winfo_width(),min(available_width,preferred_width),body.winfo_reqwidth()+2,
                          *(sum(w.winfo_reqwidth()+6 for w in row_controls)+12 for _,row_controls in wrap_groups))
        width=min(available_width,desired_width)
        def arrange_rows(content_width):
            row_width=max(1,content_width-12)
            for row,row_controls in wrap_groups:
                x=y=row_height=0
                for control in row_controls:
                    item_width=min(row_width,control.winfo_reqwidth())
                    item_height=control.winfo_reqheight()
                    if x and x+item_width>row_width:x=0;y+=row_height+3;row_height=0
                    control.place(x=x,y=y,width=item_width,height=item_height)
                    x+=item_width+6;row_height=max(row_height,item_height)
                row.configure(width=row_width,height=y+row_height)
        arrange_rows(width-2)
        viewport.itemconfigure(content,width=max(1,width-2))
        popup.update_idletasks()
        content_height=body.winfo_reqheight()
        x,y,width,height,direction=fit_popup(area,widget_rect(anchor),(width,content_height+2),side=parent is not None,
            expand=bool(getattr(menu,'_board_expand_full',False)))
        popup._popup_direction=direction
        if content_height+2>height:
            scrollbar.pack(side='right',fill='y')
            inner_width=max(1,width-scrollbar.winfo_reqwidth()-2)
            arrange_rows(inner_width);viewport.itemconfigure(content,width=inner_width)
            popup.update_idletasks();content_height=body.winfo_reqheight()
        viewport.configure(width=max(1,width-2),height=max(1,height-2),scrollregion=(0,0,width,content_height))
        def scroll(event):
            if content_height+2>height:viewport.yview_scroll(-int(event.delta/120) or (-1 if event.delta>0 else 1),'units')
            return 'break'
        popup.bind('<MouseWheel>',scroll,add='+')
        popup.geometry(f'{width}x{height}{x:+d}{y:+d}')
        popup.update_idletasks();popup.deiconify();popup.lift()
        if controls and parent is None:
            first=controls[0]
            if isinstance(first,ttk.Entry):
                popup.after_idle(lambda entry=first:entry.focus_force() if entry.winfo_exists() else None)
            else:first.focus_set()
        popup.bind('<Escape>',lambda _e:self.close_dropdown())
        def focus_left(_event=None):
            def check():
                if self._dropdown_popup is not popup:return
                focused=popup.focus_get()
                if focused is None or (focused is not popup and not str(focused).startswith(str(popup)+'.')):self.close_dropdown()
            popup.after_idle(check)
        popup.bind('<FocusOut>',focus_left,add='+')
        def outside(event):
            if event.widget is self or str(event.widget).startswith(str(popup)+'.'):return
            self.close_dropdown()
        self._outside_binding=root.bind('<ButtonPress-1>',outside,add='+')

