BOARD_VERSION = '2026-09-19-native-instance-diagnostics'

def save_json(path, value):
    from board_runtime_reliability import atomic_json
    atomic_json(path,value)

def load_json(path, default=None):
    try:
        return json.loads(path.read_text(encoding='utf-8'))
    except (OSError, ValueError):
        return {} if default is None else default

def reload_capture_allowed(plan,capture):
    if (plan.get('game_default_positions') or not plan.get('restore_capture') or
            not isinstance(capture,dict) or not capture.get('enabled')):return False
    positions=capture.get('positions',{})
    if not isinstance(positions,dict) or not positions:return False
    has_teammates=any(str(slot)!=str(plan.get('me_slot')) for slot in positions)
    return not has_teammates or bool(plan.get('ai_plan'))

def write_board_status(state, **values):
    record = {'time': datetime.now().isoformat(timespec='milliseconds'),
              'version': BOARD_VERSION, 'state': state, **values}
    save_json(STATUS_PATH, record)
    with (BOARD_LOG_ROOT / 'GPT-6 RE6 Cheat Board.log').open('a', encoding='utf-8') as log:
        log.write(json.dumps(record, ensure_ascii=False, allow_nan=False) + '\n')
    return record

def new_log_batch(prefix):
    root=BOARD_LOG_ROOT/'runs'; root.mkdir(exist_ok=True)
    folder=root/(prefix+'_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    folder.mkdir(exist_ok=False)
    import os
    save_json(folder/'owner.json',{'pid':os.getpid()})
    return folder

def prune_log_batches():
    import shutil
    import ctypes as C
    root=(BOARD_LOG_ROOT/'runs').resolve()
    if not root.exists(): return
    directories=sorted((p for p in root.iterdir() if p.is_dir() and p.name.startswith(('board_','player_action_'))),
                       key=lambda p:p.name.split('_',2)[-1] if p.name.startswith('player_action_') else p.name[6:],reverse=True)
    k=C.WinDLL('kernel32',use_last_error=True)
    k.OpenProcess.argtypes=[C.c_uint32,C.c_int,C.c_uint32]; k.OpenProcess.restype=C.c_void_p
    k.WaitForSingleObject.argtypes=[C.c_void_p,C.c_uint32]; k.WaitForSingleObject.restype=C.c_uint32
    k.CloseHandle.argtypes=[C.c_void_p]
    completed=[]; active=[]
    for p in directories:
        if (p/'complete.json').is_file(): completed.append(p); continue
        owner=load_json(p/'owner.json').get('pid')
        h=k.OpenProcess(0x100000,False,int(owner)) if owner else None
        if h:
            try: running=k.WaitForSingleObject(h,0)==258
            finally: k.CloseHandle(h)
        else: running=bool(owner and C.get_last_error()==5)
        (active if running else completed).append(p)
    old_rounds=[p for p in completed if p.name.startswith('board_')][12:]
    old_actions=[p for p in completed if p.name.startswith('player_action_')][10:]
    for folder in old_rounds+old_actions:
        if folder.is_symlink() or folder.is_junction() or folder.resolve().parent!=root: continue
        try: shutil.rmtree(folder)
        except OSError: pass
    from logging.handlers import RotatingFileHandler
    log=BOARD_LOG_ROOT/'GPT-6 RE6 Cheat Board.log'
    if log.exists() and log.stat().st_size>2*1024*1024:
        handler=RotatingFileHandler(log,maxBytes=2*1024*1024,backupCount=2,encoding='utf-8')
        try: handler.doRollover()
        finally: handler.close()

def migrate_saved_settings():
    for path in (PLAN_PATH,REPEAT_PATH,RESPAWN_PATH):
        old=BOARD_ROOT/path.name
        if not path.exists() and old.exists(): save_json(path,load_json(old))

def system_language():
    import ctypes as C
    try: return 'zh' if C.windll.kernel32.GetUserDefaultUILanguage() & 0x3ff == 4 else 'en'
    except OSError: return 'en'

def system_dark_mode():
    import winreg
    try:
        key=winreg.OpenKey(winreg.HKEY_CURRENT_USER,r'Software\Microsoft\Windows\CurrentVersion\Themes\Personalize')
        value,_=winreg.QueryValueEx(key,'AppsUseLightTheme'); key.Close()
        return int(value)==0
    except (OSError,ValueError): return False

