def theme_titlebar(window,dark,bg,fg):
    """Apply native caption colors without flushing the entire Tk event queue."""
    try:
        import ctypes as C
        from ctypes import wintypes as W
        api=getattr(theme_titlebar,'_native_api',None)
        if api is None:
            user=C.WinDLL('user32',use_last_error=True)
            dwm=C.WinDLL('dwmapi',use_last_error=True)
            user.GetAncestor.argtypes=[W.HWND,W.UINT];user.GetAncestor.restype=W.HWND
            user.RedrawWindow.argtypes=[W.HWND,C.c_void_p,W.HANDLE,W.UINT]
            user.RedrawWindow.restype=W.BOOL
            dwm.DwmSetWindowAttribute.argtypes=[W.HWND,W.DWORD,C.c_void_p,W.DWORD]
            dwm.DwmSetWindowAttribute.restype=C.c_long
            api=theme_titlebar._native_api=(user,dwm)
        user,dwm=api
        # winfo_id is the client; DWM colors belong to its native wrapper.
        # Map handlers reapply after Tk recreates the caption or alpha style.
        client=window.winfo_id();hwnd=user.GetAncestor(client,2) or client
        dark_mode=C.c_int(bool(dark))
        for attribute in (20,19):
            dwm.DwmSetWindowAttribute(hwnd,attribute,C.byref(dark_mode),C.sizeof(dark_mode))
        def colorref(value):
            value=value.lstrip('#')
            r,g,b=(int(value[i:i+2],16) for i in (0,2,4))
            return r | (g<<8) | (b<<16)
        for attribute,value in ((35,bg),(36,fg)):
            color=C.c_int(colorref(value))
            dwm.DwmSetWindowAttribute(hwnd,attribute,C.byref(color),C.sizeof(color))
        # INVALIDATE | FRAME | NOCHILDREN. No UPDATENOW: native decoration
        # repaint must not synchronously redraw every Board child control.
        user.RedrawWindow(hwnd,None,None,0x0001 | 0x0400 | 0x0040)
    except Exception:
        return

