def localize_message(message, language='zh'):
    """Translate status/error text at the UI boundary; raw diagnostics stay in files."""
    text=str(message).strip()
    if language!='zh' or not text:
        from board_english_display import english
        return english(text)
    exact=ZH_STATUS.get(text,ZH_TEXT.get(text))
    if exact is not None:return exact
    if text.startswith('Delete this custom options backup?\n'):
        return '是否删除这份自定义选项备份？\n'+text.split('\n',1)[1]
    if text.startswith('Custom options restored: '):return '已恢复自定义选项：'+text[25:]
    if text.startswith('Backup deletion failed: '):return '删除备份失败：'+localize_message(text[24:],language)
    match=re.fullmatch(r'Model caches refreshed (\d+), pending (\d+); enemy XYZ locked (\d+); topmost (on|off)',text)
    if match:return (f'模型缓存已重建 {match[1]}，待处理 {match[2]}；敌人坐标锁定 {match[3]}；'
                     f"游戏置顶：{'开' if match[4]=='on' else '关'}")
    for prefix,label in (('Action stopped: ','操作已停止：'),('Player monitor: ','角色监控：'),
                         ('Scene tools: ','场景工具：'),('场景工具：','场景工具：'),
                         ('Scene helper cleanup: ','场景维护清理：'),
                         ('Auto rotation stopped: ','自动旋转已停止：'),
                         ('Captured positions skipped; remaining round steps will continue: ','恢复位置未完成，继续其他任务：'),
                         ('AI teammate relocation skipped; EM4700 spawning will continue: ','队友排列未完成，继续生成敌人：'),
                         ('Spawned EM4700 was not registered for protected teleport: ','EM4700 已生成，但未能登记到保护列表：')):
        if text.startswith(prefix):return label+localize_message(text[len(prefix):],language)
    match=re.fullmatch(r'(?:ValueError|RuntimeError|TimeoutError|OSError|PermissionError|TypeError): (.*)',text,re.S)
    if match:return localize_message(match[1],language)
    match=re.fullmatch(r"NameError: name '([^']+)' is not defined.*",text,re.S)
    if match:return f'脚本内部缺少名称 {match[1]}，任务未完成；详细错误已写入日志。'
    match=re.fullmatch(r'Expected one BH6.exe, found (\[.*\]); specify --pid if needed\.',text)
    if match:return '等待连接游戏进程。' if match[1]=='[]' else '检测到多个游戏进程，暂时无法确定控制目标。'
    match=re.fullmatch(r'Queue ended \(exit (-?\d+)\)\.',text)
    if match:return '重载队列已结束。' if match[1]=='0' else f'重载队列异常退出，错误代码 {match[1]}；详细原因已写入日志。'
    if text.startswith('Queue failed: '):return '重载任务失败：'+localize_message(text[14:],language)
    match=re.fullmatch(r'BH6 process (attached|reconnected) \(PID (\d+)\)\.',text)
    if match:return f"{'已自动连接' if match[1]=='attached' else '已自动重新连接'} BH6 游戏进程（PID {match[2]}）。"
    if text=='BH6 process lost; waiting for a new process.':return '游戏进程已退出，正在等待新进程并自动重连。'
    if text=='BH6 process not found; waiting to attach automatically.':return '暂未发现游戏进程，启动游戏后将自动连接。'
    match=re.fullmatch(r'Queue (restore_positions|formation): (\d+)/(\d+) applied\.',text)
    if match:return f"{'恢复位置' if match[1]=='restore_positions' else '队友排列'}：游戏线程已完成 {match[2]}/{match[3]}。"
    match=re.fullmatch(r'(.+) must be a number\.',text)
    if match:return ZH_STATUS.get(match[1],match[1])+'必须是数字。'
    match=re.fullmatch(r'(.+) must be (-?[\d.]+)\.\.(-?[\d.]+)\.',text)
    if match:return f'{ZH_STATUS.get(match[1],match[1])}必须为 {match[2]} 至 {match[3]}。'
    match=re.fullmatch(r'Queued (\w+); player actions run one at a time\.',text)
    if match:return ZH_STATUS.get(match[1],'操作')+'已加入队列，正在按顺序执行。'
    match=re.fullmatch(r'(\w+): (running on game thread|\d+/\d+ applied|\w+)',text)
    if match:
        detail='正在游戏线程执行' if match[2]=='running on game thread' else match[2].replace(' applied',' 已完成')
        return ZH_STATUS.get(match[1],match[1])+'：'+ZH_STATUS.get(detail,detail)
    match=re.fullmatch(r'Selected teammate slot (\d+) is not loaded or transform-ready\.',text)
    if match:return f'所选队友槽位 {match[1]} 尚未加载，或坐标尚未就绪。'
    match=re.fullmatch(r'The controlled (\w+) body is excluded; no other eligible enemy is ready to teleport\.',text)
    if match:return '你操控的 '+match[1]+' 不能作为传送目标；当前没有其它就绪、可传送的同类敌人。'
    match=re.fullmatch(r'No ready (\w+) enemies are registered in this scene\.',text)
    if match:return f'当前场景没有可操作的 {match[1]}。'
    match=re.fullmatch(r'No live Board-created (\w+) is registered; story enemies were left untouched\.',text)
    if match:return f'当前没有本工具生成且仍可用的 {match[1]}，剧情敌人已保留。'
    match=re.fullmatch(r'QTE command for slot (\d+) was not acknowledged; pause retained\.',text)
    if match:return f'槽位 {match[1]} 的 QTE 操作未收到确认，暂停状态已保留。'
    if text.startswith('QTE progression timed out for slots '):return '以下槽位的 QTE 推进超时：'+text.split('slots ',1)[1]
    if text.startswith('Checked slots: '):return '已勾选槽位：'+text[15:].replace('none','无')
    if text.startswith('Waiting for scene reload. ALWAYS APPLY: '):return '等待重新加载场景；每局自动应用：'+('开' if text.endswith('ON') else '关')
    if text.startswith('Position saved: '):return '已保存位置：'+text[16:]
    if 'could not convert string to float' in text or 'invalid literal for int()' in text:return '请输入有效数字，不能留空或包含文字。'
    if text.startswith('No ready actors matched the selected slots: ') or text.startswith('Targets changed after reload: '):
        prefix='所选角色暂不可操作：' if text.startswith('No ready') else '重新加载后，部分目标已改变：'
        try:
            records=json.loads(text.split(': ',1)[1])
            return prefix+'；'.join(f"槽位 {r.get('slot',r.get('enemy_slot','?'))}：{localize_message(r.get('reason','unknown'),language)}" for r in records[:8])
        except (ValueError,TypeError,AttributeError):return prefix+'详情已记录到日志。'
    if text.startswith(('[WinError ','[Errno ')):
        code=re.search(r'\[(?:WinError|Errno) (\d+)\]',text)
        number=int(code[1]) if code else 0
        return {5:'没有权限访问游戏进程，请用与游戏相同的权限运行修改器。',
                6:'游戏进程句柄已失效，请等待重新连接。',299:'游戏正在切换或对象已释放，内存读取未完成。',
                87:'系统调用参数无效，本次操作已停止。'}.get(number,f'Windows 操作失败，错误代码 {number}；详细原因已记录到日志。')
    # These families preserve the cause for all native identity/build guards.
    groups=((('Scene changed','Scene or','Scene manager','Scene definition','Enemy registry changed'), '场景或对象已切换，本次操作已停止，请等待场景就绪后重试。'),
            (('Player identity','Player manager/slot','Player type','Player body','Parent identity','Child identity','Object vector','Manager metadata','Process changed','Process identity'), '角色或进程在读取过程中发生变化，请重新执行。'),
            (('Enemy identity','Enemy Intel owner','Enemy or player','Enemy slots changed','Enemy manager changed','Extra enemy Intel','Extra enemy identity','Enemy vector','Target binding identity','Target identity'), '敌人或目标对象已改变，请重新执行。'),
            (('Enemy manager class','Enemy manager mismatch','sEnemy manager','Unsupported','Native target predicate','Teammate setter','Resource manager','New EM4700','EM4700 QTE','EM4700 transform','QTE initializer','QTE failure','QTE success','Enemy target setter'), '游戏代码或对象结构与已验证版本不匹配，操作已停止。'),
            (('Scene helper code','Grab pause code','QTE timer','Transform batch','Transform data','Streaming cave','Target binding code','Code page','Stage cave','Target filter','Resource payload','Expected allocation'), '本次操作超出已分配的内存容量，未继续执行。'),
            (('Implausible','Unexpected resource','Invalid PE','Invalid action','Action owner','Invalid partner','Invalid player position','Non-finite placement','EM4700 type','Resource moved','Resource evidence','EM4700 model'), '读取到的游戏对象或资源数据无效，操作已停止。'),
            (('Per-instance target table','Target-filter dispatch','Native claim sequence','Native transform signature'), '游戏钩子或代码回读校验失败，操作已停止。'),
            (('No thread contexts','Expected repeated group','Prepare thread contexts'), '无法取得稳定的游戏线程状态，请稍后重试。'))
    for prefixes,label in groups:
        if text.startswith(prefixes):return label
    # Already localized messages may contain actor IDs, QTE, XYZ, and paths.
    if re.search(r'[\u4e00-\u9fff]',text):return text
    # Preserve an unfamiliar backend result instead of concealing its cause.
    return '操作返回：'+text

