class LocalizedStatus(tk.StringVar):
    def __init__(self, app, value=''):
        self.app=app;self.source=value
        super().__init__(master=app.root,value=localize_message(value,app.language))
    def set(self,value):
        self.source=str(value)
        super().set(localize_message(value,self.app.language))
    def relocalize(self):self.set(self.source)

def normalize_qte_timeline(points):
    """Validate the eight-slot time graph used by both delayed actions."""
    if not isinstance(points,(list,tuple)) or len(points)!=8:
        raise ValueError('QTE timeline must contain exactly eight SLOT points.')
    result=[]
    for value in points:
        if value is None:result.append(None);continue
        if type(value) is bool or type(value) is not int or not -1<=value<8:
            raise ValueError('QTE timeline points must be empty, random, or rows 1..8.')
        result.append(value)
    if not any(value is not None for value in result):
        raise ValueError('Select at least one QTE slot.')
    return result

def qte_timeline_from_legacy(app):
    """Map the former simultaneous/progressive/random groups to time rows."""
    points=[None]*8
    grouped={}
    for slot in range(8):
        if not getattr(app,f'delayed_qte_slot_{slot}').get():continue
        group=getattr(app,f'delayed_qte_group_{slot}').get()
        if group==7:points[slot]=-1
        elif 1<=group<=6:grouped.setdefault(group,[]).append(slot)
    for group,slots in grouped.items():
        if group<=3:row={1:0,2:3,3:6}[group]
        else:
            ordered=sorted(slots)
            for index,slot in enumerate(ordered):
                points[slot]=round(index*7/max(1,len(ordered)-1))
            continue
        for slot in slots:points[slot]=row
    return points

def qte_timeline_preset(name):
    presets={
        'same_batch':[0]*8,
        'linear':list(range(8)),
        'pattern':[0,0,2,2,5,5,7,7],
        'wave':[4,1,0,2,5,7,6,4],
        'random':[-1]*8,
    }
    return list(presets.get(name,presets['same_batch']))

def migrate_qte_delay_settings(saved):
    """Upgrade old default ranges once; later user edits remain authoritative."""
    saved=dict(saved)
    if saved.get('qte_delay_range_revision') not in (2,):
        try:
            low=float(saved.get('scatter_delay_min',.1))
            high=float(saved.get('scatter_delay_max',6))
            if 0<=low<=6 and high in (.6,2):saved['scatter_delay_max']=6.0
        except (ValueError,TypeError,OverflowError):pass
    saved['qte_delay_range_revision']=2
    return saved

class QteTimelineChart(tk.Canvas):
    """Small point-only editor: one draggable point per SLOT, eight time rows."""
    def __init__(self,master,points,low,high,translate,editable=True,on_change=None,**kwargs):
        super().__init__(master,highlightthickness=0,**kwargs)
        self.points=points;self.low=low;self.high=high;self.translate=translate
        self.editable=editable;self.on_change=on_change;self._drag=None;self._focus_slot=None
        self.bind('<Configure>',lambda _e:self.redraw())
        if editable:
            self.bind('<Button-1>',self._press);self.bind('<B1-Motion>',self._motion);self.bind('<ButtonRelease-1>',self._release)
            self.bind('<KeyPress-Up>',lambda _e:self._keyboard(-1));self.bind('<KeyPress-Down>',lambda _e:self._keyboard(1))
            self.bind('<Delete>',lambda _e:self._clear_focused())
        self.redraw()

    def set_points(self,points):self.points=points;self.redraw()
    def _metrics(self):
        width=max(1,self.winfo_width());height=max(1,self.winfo_height())
        return width,height,94,34,max(1,(width-118)/8),max(1,(height-102)/8)
    def _cell(self,event):
        width,height,left,top,cw,ch=self._metrics()
        slot=math.floor((event.x-left)/cw);row=math.floor((event.y-top)/ch)
        return (slot,row) if 0<=slot<8 and 0<=row<8 else (None,None)
    def _press(self,event):
        slot,row=self._cell(event)
        if slot is None:return
        self.focus_set();current=self.points[slot]
        self._focus_slot=slot;self._drag=(slot,current,row,False)
    def _motion(self,event):
        if self._drag is None:return
        slot,initial,row0,moved=self._drag;_,row=self._cell(event)
        if row is None:return
        if row!=row0 or moved:
            self.points[slot]=row;self._drag=(slot,initial,row,True);self.redraw()
            if self.on_change:self.on_change()
    def _release(self,event):
        if self._drag is None:return
        slot,initial,row,moved=self._drag;self._drag=None
        if not moved:
            self.points[slot]=row if initial in (None,-1) else None
            self.redraw()
            if self.on_change:self.on_change()
    def _keyboard(self,delta):
        if self._focus_slot is None:return
        slot=self._focus_slot;value=self.points[slot]
        if value is None:value=0
        self.points[slot]=max(0,min(7,value+delta));self.redraw()
        if self.on_change:self.on_change()
    def _clear_focused(self):
        if self._focus_slot is not None:
            self.points[self._focus_slot]=None;self.redraw()
            if self.on_change:self.on_change()
    def redraw(self):
        if not self.winfo_exists():return
        width,height,left,top,cw,ch=self._metrics();app=getattr(self,'app',None);dark=getattr(app,'dark_mode',None)
        bg='#202226' if getattr(dark,'get',lambda:False)() else '#eeeeef';fg='#e8eaed' if bg!='#eeeeef' else '#25272a'
        self.configure(background=bg);self.delete('all')
        self.create_text(8,14,anchor='w',text=self.translate('Time axis'),fill=fg,font=('Microsoft YaHei',10,'bold'))
        self.create_text(8,top+ch/2,anchor='w',text=self.translate('Fast'),fill=fg,font=('Microsoft YaHei',9))
        self.create_text(8,top+7*ch+ch/2,anchor='w',text=self.translate('Slow'),fill=fg,font=('Microsoft YaHei',9))
        for slot in range(8):
            x=left+(slot+.5)*cw;self.create_text(x,14,text=f'SLOT {slot}',fill=fg,font=('Microsoft YaHei',9,'bold'))
        for row in range(8):
            y=top+(row+.5)*ch
            try:seconds=float(self.low)+(float(self.high)-float(self.low))*row/7
            except (TypeError,ValueError):seconds=0
            self.create_text(left-10,y,anchor='e',text=f'{seconds:.2f}s',fill=fg,font=('Microsoft YaHei',8))
            self.create_line(left,y,left+8*cw,y,fill='#59616d',dash=(2,4))
            for slot in range(8):
                x=left+(slot+.5)*cw;self.create_oval(x-2,y-2,x+2,y+2,fill='#59616d',outline='')
        for slot,value in enumerate(self.points):
            if value is None:continue
            if value==-1:
                y=top+8*ch+22;fill='#e69b42'
            else:
                y=top+(value+.5)*ch;fill='#3d9be9'
            x=left+(slot+.5)*cw
            self.create_oval(x-9,y-9,x+9,y+9,fill=fill,outline='#dcefff',width=2)
        self.create_text(left,top+8*ch+42,anchor='w',text=self.translate('Orange points use random timing.'),fill=fg,font=('Microsoft YaHei',9))

