def _write_startup_policy_report():
    """Persist compatibility decisions without turning them into a crash."""
    if not _BOARD_STARTUP_PATCH_ERRORS:
        return
    try:
        BOARD_LOG_ROOT.mkdir(parents=True, exist_ok=True)
        (BOARD_LOG_ROOT/'startup_policy.json').write_text(
            json.dumps(dict(policy=_BOARD_STARTUP_POLICY,
                            events=_BOARD_STARTUP_PATCH_ERRORS),
                       ensure_ascii=False, indent=2),
            encoding='utf-8')
    except (OSError, TypeError):
        pass

