    def say(self, message):
        original=str(message)
        message=localize_message(original,self.language)
        try:
            with (BOARD_LOG_ROOT / 'GPT-6 RE6 Cheat Board.log').open('a', encoding='utf-8') as stream:
                stream.write(json.dumps({'time':datetime.now().isoformat(timespec='milliseconds'),
                                         'message':message,'diagnostic':original}, ensure_ascii=False) + '\n')
        except OSError:
            pass
        # The log is file-only; rendering a hidden Text widget wasted UI time.

    def bind_tooltip(self,widget,text):
        pending=None
        window=None
        def hide(_event=None):
            nonlocal pending,window
            if pending is not None:
                self.root.after_cancel(pending);pending=None
            if window is not None:
                if window.winfo_exists():window.destroy()
                window=None
        def show():
            nonlocal pending,window
            pending=None
            if not widget.winfo_exists() or not widget.winfo_ismapped():return
            window=tk.Toplevel(self.root);window.withdraw()
            window.overrideredirect(True);window.attributes('-topmost',True)
            dark=self.dark_mode.get()
            bg='#303339' if dark else '#f6f7f9';fg='#e8eaed' if dark else '#25272a'
            label=tk.Label(window,text=self.translate(text() if callable(text) else text),justify='left',anchor='w',wraplength=440,
                           background=bg,foreground=fg,font=('Microsoft YaHei',10),
                           padx=12,pady=9,relief='solid',borderwidth=1)
            label.pack();window.update_idletasks()
            width,height=window.winfo_reqwidth(),window.winfo_reqheight()
            x=widget.winfo_rootx();y=widget.winfo_rooty()+widget.winfo_height()+6
            x=min(x,self.root.winfo_rootx()+self.root.winfo_width()-width-8)
            if y+height>self.root.winfo_rooty()+self.root.winfo_height():
                y=widget.winfo_rooty()-height-6
            window.geometry(f'{width}x{height}{x:+d}{y:+d}')
            window.deiconify()
        def enter(_event):
            nonlocal pending
            hide();pending=self.root.after(350,show)
        widget.bind('<Enter>',enter,add='+')
        for event in ('<Leave>','<ButtonPress>','<Destroy>'):
            widget.bind(event,hide,add='+')
        widget._hide_tooltip=hide
        widget._tooltip_text=text

    def install_flow_layout(self,container,exclude=()):
        self.flow_rows=[]
        def walk(parent):
            # Split buttons keep their natural width and wrap as one control.
            if parent in exclude or getattr(parent,'_flow_atomic',False):return
            for child in parent.winfo_children():walk(child)
            packed=parent.pack_slaves()
            if (len(packed)>1 and all((w.winfo_class() in ('TLabel','TButton','TMenubutton','TEntry','TSpinbox',
                    'TCombobox','TCheckbutton','TRadiobutton') or getattr(w,'_flow_atomic',False))
                    and w.pack_info().get('side') in ('left','right') for w in packed)):
                groups=[]
                for widget in packed:
                    if groups and ((groups[-1][-1].winfo_class()=='TLabel' and widget.winfo_class() in ('TEntry','TSpinbox','TCombobox'))
                                   or (groups[-1][-1].winfo_class()=='TButton' and widget.winfo_class()=='TMenubutton')):
                        groups[-1].append(widget)
                    else:groups.append([widget])
                for widget in packed:widget.pack_forget()
                parent.pack_propagate(False)
                self.flow_rows.append((parent,groups))
                parent.bind('<Configure>',lambda _e,p=parent,g=groups:self.layout_flow_row(p,g),add='+')
        walk(container)
        self.root.after_idle(self.reflow_controls)

    def layout_flow_row(self,parent,groups):
        if not parent.winfo_exists():return
        available=max(100,parent.winfo_width());rows=[];row=[];used=0
        for group in groups:
            if not group:
                if row:rows.append(row)
                row=[];used=0
                continue
            sizes=[(max(16,w.winfo_reqwidth()),max(20,w.winfo_reqheight())) for w in group]
            width=sum(v[0] for v in sizes)+4*(len(group)-1)
            if row and used+width>available:
                rows.append(row);row=[];used=0
            for widget,(width,height) in zip(group,sizes):
                # A label/input group may itself exceed a narrow window.
                if row and used+min(width,available)>available:
                    rows.append(row);row=[];used=0
                width=min(width,available)
                row.append((widget,used,width,height));used+=width+4
            used+=4
        if row:rows.append(row)
        y=0
        for row in rows:
            row_h=max(item[3] for item in row)
            for widget,x,width,height in row:
                offset=row_h-height if getattr(parent,'_flow_bottom_align',False) else (row_h-height)//2
                geometry=(x,y+offset,width,height)
                if getattr(widget,'_flow_geometry',None)!=geometry:
                    widget.place(x=geometry[0],y=geometry[1],width=width,height=height)
                    widget._flow_geometry=geometry
            y+=row_h+6
        height=max(24,y-6)
        if int(parent.cget('height'))!=height:parent.configure(height=height)

    def layout_formation_controls(self):
        block,fields,rotation,positions=self.formation_layout
        if not block.winfo_exists():return
        def natural_width(frame):
            return sum(child.winfo_reqwidth()+8 for child in frame.winfo_children())
        left=max(natural_width(fields),natural_width(rotation))
        right=positions.winfo_reqwidth()+6
        wide=block.winfo_width()>=left+right
        layout=(wide,left if wide else 0)
        if getattr(block,'_formation_layout',None)==layout:return
        block._formation_layout=layout
        block.columnconfigure(0,weight=0 if wide else 1,minsize=left if wide else 0)
        block.columnconfigure(1,weight=1 if wide else 0)
        fields.grid_configure(columnspan=1 if wide else 2)
        rotation.grid_configure(columnspan=1 if wide else 2)
        positions.grid_configure(row=0 if wide else 2,column=1 if wide else 0,
                                 rowspan=2 if wide else 1,columnspan=1 if wide else 2,
                                 padx=(6,0) if wide else 0,pady=0 if wide else (4,0))

    def reflow_controls(self):
        if hasattr(self,'formation_layout'):self.layout_formation_controls()
        for parent,groups in getattr(self,'flow_rows',[]):self.layout_flow_row(parent,groups)

    def scroll_main(self,event):
        widget=event.widget
        if isinstance(widget,str):
            try:widget=self.root.nametowidget(widget)
            except (KeyError,tk.TclError):return
        try:
            if widget.winfo_toplevel()!=self.root:return
            if widget.winfo_class() in ('TSpinbox','TCombobox','Treeview','Listbox'):return
        except (AttributeError,tk.TclError):return
        self.main_canvas.yview_scroll(-int(event.delta/120),'units')

    def remember_window(self,event=None):
        if event is not None and event.widget!=self.root:return
        if self._window_changing:return
        state=self.root.state()
        if state in ('normal','zoomed'):self._window_maximized=state=='zoomed'
        if state=='normal' and self.root.winfo_width()>300:
            self._window_normal=dict(width=self.root.winfo_width(),height=self.root.winfo_height(),
                                     x=self.root.winfo_x(),y=self.root.winfo_y())

    def save_window_preferences(self):
        self.remember_window()
        if not self._window_normal:return
        saved=load_json(WINDOW_PATH)
        if not isinstance(saved,dict):saved={}
        sizes=saved.get('sizes',{})
        if not isinstance(sizes,dict):sizes={}
        current=self._window_normal
        sizes[self.language]={key:current[key] for key in ('width','height')}
        save_json(WINDOW_PATH,{'version':2,'sizes':sizes,'x':current['x'],'y':current['y'],
                               'maximized':self._window_maximized})

    def restore_window(self):
        saved=load_json(WINDOW_PATH)
        if not isinstance(saved,dict):saved={}
        sizes=saved.get('sizes',{})
        size=sizes.get(self.language,{}) if isinstance(sizes,dict) else {}
        if not isinstance(size,dict):size={}
        if 'sizes' not in saved:size=saved
        sw,sh=self.root.winfo_screenwidth(),self.root.winfo_screenheight()
        width,height=min(1400 if self.language=='en' else 1200,sw-40),min(940,sh-80)
        try:
            width=max(680,min(int(size.get('width',width)),sw))
            height=max(450,min(int(size.get('height',height)),sh))
            x=int(saved.get('x',(sw-width)//2));y=int(saved.get('y',(sh-height)//2))
            import ctypes as C
            from ctypes import wintypes as W
            class MonitorInfo(C.Structure):
                _fields_=[('size',W.DWORD),('monitor',W.RECT),('work',W.RECT),('flags',W.DWORD)]
            u=C.WinDLL('user32');u.MonitorFromRect.argtypes=[C.POINTER(W.RECT),W.DWORD];u.MonitorFromRect.restype=W.HANDLE
            u.GetMonitorInfoW.argtypes=[W.HANDLE,C.POINTER(MonitorInfo)]
            rect=W.RECT(x,y,x+width,y+height);info=MonitorInfo();info.size=C.sizeof(info)
            if u.GetMonitorInfoW(u.MonitorFromRect(C.byref(rect),2),C.byref(info)):
                area=info.work;width=min(width,area.right-area.left);height=min(height,area.bottom-area.top)
                x=max(area.left,min(x,area.right-width));y=max(area.top,min(y,area.bottom-height))
        except (ValueError,TypeError,OSError):x=max(0,(sw-width)//2);y=max(0,(sh-height)//2)
        self.root.minsize(min(680,sw),min(450,sh))
        self.root.geometry(f'{width}x{height}{x:+d}{y:+d}')
        self._window_normal=dict(width=width,height=height,x=x,y=y)
        self._restore_maximized=bool(saved.get('maximized',False))
        self._window_maximized=self._restore_maximized

    def dismiss_editor_on_blank(self,event):
        """Commit editors and dismiss row highlights on empty-space clicks."""
        try:
            widget_class=event.widget.winfo_class()
        except (AttributeError,tk.TclError):
            return
        if widget_class in {'Entry','TEntry','Spinbox','TSpinbox',
                            'Combobox','TCombobox','Text'}:
            return
        try:
            window=event.widget.winfo_toplevel()
            window.focus_set()
            blank=widget_class in {'Frame','TFrame','Labelframe','TLabelframe',
                                   'Canvas','Tk','Toplevel','Label','TLabel'}
            if widget_class=='Treeview':
                blank=(not event.widget.identify_row(event.y)
                       and event.widget.identify_region(event.x,event.y) not in {'heading','separator'})
            if blank:
                # A combobox can select its text on a wheel event without
                # taking keyboard focus. Clearing only focus leaves that
                # selection painted, so clear editors throughout this window.
                pending=[window]
                while pending:
                    child=pending.pop()
                    if child.winfo_toplevel()!=window:
                        continue
                    if child.winfo_class() in {'Entry','TEntry','Spinbox','TSpinbox',
                                                'Combobox','TCombobox'}:
                        child.selection_clear()
                    elif child.winfo_class()=='Text':
                        child.tag_remove('sel','1.0','end')
                    pending.extend(child.winfo_children())
                trees=[event.widget] if widget_class=='Treeview' else [getattr(self,'tree',None)]
                for tree in trees:
                    if tree is not None and tree.winfo_toplevel()==window:
                        selected=tree.selection()
                        if selected:tree.selection_remove(*selected)
                        tree.focus('')
        except tk.TclError:
            pass

    def update_spawn_candidate(self):
        name=self.spawn_candidate.get()
        if name not in SPAWN_CANDIDATE_NAMES:return
        label=name[1:].upper() if name.startswith('u') else name
        for widget,source in self._spawn_caption_widgets:
            widget.configure(text=self.translate(source).replace('EM4700',label))
        current=load_json(PLAN_PATH);current['spawn_candidate']=name;save_json(PLAN_PATH,current)
        self.close_spawn_search()
        if hasattr(self,'reload_flow'):self.root.after_idle(lambda:self.layout_flow_row(*self.reload_flow))

    def show_enemy_placeholder(self,kind):
        self.update_spawn_candidate()
        message=('Choose a candidate identifier. Spawning other enemies is reserved for later research.' if kind=='spawn' else
                 'Reserved: play the selected enemy in a normal campaign using Agent Hunt controls.')
        self.show_dialog('info','Reserved feature',self.spawn_candidate.get()+'\n'+self.translate(message))

    def show_em4700_placeholder(self,recall):
        label='Keep EM4700 assembled' if recall else 'One-click kill EM4700'
        message=('Reserved: continuously detect separated EM4700 parts and make them return to their own host and rejoin. This button does not execute yet.' if recall else
                 'Reserved: kill EM4700 through its native death sequence and play the burst animation. This button does not execute yet.')
        self.show_dialog('info','Reserved feature',self.translate(label)+'\n'+self.translate(message))

    def toggle_em4700_preview(self,kind):
        if kind!='recall':return
        if getattr(self,'em4700_recall_cancel',None) is not None:
            self.stop_em4700_recall()
            self.player_action_status.set('EM4700 自动寻回已停止；已提交的原生动作由游戏继续处理。' if self.language=='zh' else 'EM4700 reassembly stopped; already submitted native actions may finish.')
            return
        self.em4700_recall_cancel=threading.Event()
        self.em4700_preview_running['recall']=True
        self.update_em4700_recall_button()
        self.player_action_status.set('EM4700 自动寻回已开启。' if self.language=='zh' else 'EM4700 reassembly enabled.')
        self.queue_em4700_recall(self.em4700_recall_cancel)

    def open_em4701_dropdown(self,_event=None):
        self.refresh_em4701_menu();self.em4701_dropdown.open_dropdown()
        return 'break'

    def refresh_em4701_menu(self):
        self.em4701_menu.delete(0,'end')
        for label,variable in (
            ('Prevent EM4701 from returning to its host',self.em4701_no_return),
            ('Always show hidden EM4701',self.em4701_always_show)):
            self.em4701_menu.add_checkbutton(label=self.translate(label),variable=variable,
                command=self.change_em4701_policy)

    def change_em4701_policy(self):
        self.em4701_revision+=1
        self.em4701_monitor=True
        self.em4701_policy_request=dict(flags=int(self.em4701_no_return.get())|int(self.em4701_always_show.get())*2,
            monitor=True,revision=self.em4701_revision)
        token=getattr(self,'em4701_pending',None)
        if token is not None:token.set()
        # Stop the old command; keep the user's continuous-mode selection.
        # While either exception is checked, ticks do no native work.
        previous=getattr(self,'em4700_recall_cancel',None)
        if previous is not None:
            previous.set()
            wakeup=getattr(self,'em4700_recall_wakeup',None)
            if wakeup is not None:self.root.after_cancel(wakeup)
            self.em4700_recall_cancel=threading.Event()
            self.queue_em4700_recall(self.em4700_recall_cancel)

    def release_em4701_players(self):
        if self.em4701_pending is not None:return
        self.em4701_faulted=False
        self.em4701_deferred_release=True
        self.change_em4701_policy()

    def queue_em4701_release(self,players=False,continuation=None,revision=None):
        if revision is not None and revision!=self.em4701_revision:return
        if self._closing or self.em4701_pending is not None or self.em4701_faulted:return
        settings=self.em4701_policy_request or dict(flags=0)
        if not players and not settings['flags']&2:return
        token=threading.Event()
        request=dict(continuation or {},action='em4701_release',release_players=bool(players),
            release_hidden=bool(settings['flags']&2),em4701_flags=settings['flags'],
            _em4701_token=token,_cancel=token,_report_no_targets=bool(players),
            return_until_complete=bool(players and not settings['flags']&3))
        try:self.player_actions.put_nowait(request)
        except queue.Full:
            if players:
                next_revision=self.em4701_revision if revision is None else revision
                self.root.after(200,lambda:self.queue_em4701_release(True,continuation,next_revision))
            return
        self.em4701_pending=token
        self.em4701_release_button.state(['disabled'])

    def finish_em4701_release(self,value):
        token,error,uncertain=value[:3]
        continuation=value[3] if len(value)>3 else None
        if self.em4701_pending is not token:return
        self.em4701_pending=None;self.em4701_release_button.state(['!disabled'])
        if error:
            self.player_action_status.set(('EM4701 操作未完成：' if self.language=='zh' else 'EM4701 action incomplete: ')+error)
        if uncertain:self.em4701_faulted=True
        if continuation and not error and not uncertain and not token.is_set():
            revision=self.em4701_revision
            self.root.after(250,lambda:self.queue_em4701_release(True,continuation,revision))

    def handle_em4701_policy(self,kind,value):
        if value.get('revision')!=self.em4701_revision:return
        if kind=='em4701_policy_error':
            self.player_action_status.set(('EM4701 持续选项等待：' if self.language=='zh' else 'EM4701 policy waiting: ')+value['error'])
            return
        if kind=='em4701_policy_ready':
            self.em4701_policy_ready_revision=self.em4701_revision
            if self.em4701_deferred_release:
                self.em4701_deferred_release=False;self.queue_em4701_release(True)
        elif kind=='em4701_reveal_needed' and not self.em4701_deferred_release:
            self.queue_em4701_release(False)

    def update_em4700_recall_button(self):
        label='Keep EM4700 assembled'
        if getattr(self,'em4700_recall_cancel',None) is not None:label+='\nRunning'
        self.translation_sources[str(self.em4700_recall_button)]=label
        self.em4700_recall_button.configure(text=self.translate(label))
        self.reflow_controls()

    def stop_em4700_recall(self):
        cancel=getattr(self,'em4700_recall_cancel',None)
        if cancel is not None:cancel.set()
        self.em4700_recall_cancel=None
        wakeup=getattr(self,'em4700_recall_wakeup',None)
        if wakeup is not None:
            self.root.after_cancel(wakeup)
            self.em4700_recall_wakeup=None
        self.em4700_preview_running['recall']=False
        self.update_em4700_recall_button()

    def queue_em4700_recall(self,cancel):
        self.em4700_recall_wakeup=None
        if self._closing or cancel.is_set() or getattr(self,'em4700_recall_cancel',None) is not cancel:return
        if getattr(self,'em4700_recall_pending',None) is not None:
            self.em4700_recall_wakeup=self.root.after(250,lambda:self.queue_em4700_recall(cancel))
            return
        flags=int(self.em4701_no_return.get())|int(self.em4701_always_show.get())*2
        # Independence options exclude EM4701 only; hands still return.
        request=dict(action='em4700_reassemble',continuous=True,em4701_flags=flags,
            _merge_session=cancel,_cancel=cancel)
        try:self.player_actions.put_nowait(request)
        except queue.Full:
            self.em4700_recall_wakeup=self.root.after(250,lambda:self.queue_em4700_recall(cancel))
            return
        self.em4700_recall_pending=cancel

    def finish_em4700_recall(self,value):
        cancel,error=value
        if getattr(self,'em4700_recall_pending',None) is cancel:self.em4700_recall_pending=None
        if getattr(self,'em4700_recall_cancel',None) is not cancel:return
        if error:
            # An uncertain native submission is never automatically replayed.
            self.stop_em4700_recall()
            self.player_action_status.set(('寻回已停止：' if self.language=='zh' else 'Reassembly stopped: ')+error)
        elif not self._closing and not cancel.is_set():
            self.em4700_recall_wakeup=self.root.after(400,lambda:self.queue_em4700_recall(cancel))


    def close_spawn_search(self):
        picker=getattr(self,'spawn_picker',None)
        if picker is not None:picker.close()




