    def toggle_language(self):
        self.save_window_preferences()
        state=self.root.state()
        self._window_changing=True
        try:
            if state in ('normal','zoomed'):self.root.withdraw()
            self.language='en' if self.language=='zh' else 'zh'
            save_json(LANGUAGE_PATH,{'language':self.language})
            self.apply_language()
            self.update_enemy_action_label()
            self.update_teleport_mode_labels()
            self.update_grab_buttons()
            self.update_scene_buttons()
            for name in ('progress','player_action_status','xyz_slot_status','bookmark_status','teleport_status'):
                value=getattr(self,name,None)
                if isinstance(value,LocalizedStatus):value.relocalize()
            self._last_render_signature=None
            self.refresh()
            for window in self.root.winfo_children():
                status=getattr(window,'message_status',None)
                if isinstance(status,LocalizedStatus):status.relocalize()
            self.restore_window()
            self.root.update_idletasks()
            self.reflow_controls()
        finally:
            try:
                if state in ('normal','zoomed'):
                    self.root.deiconify()
                    if self._restore_maximized:self.root.state('zoomed')
                self.root.update_idletasks()
            finally:
                self._window_changing=False
        self.remember_window()

