    def save_my_position(self):
        slot=self.me.current()
        if not 0<=slot<8:return
        def capture():
            try:
                from re6_transform_backend import cached_build,actor_record,map_fingerprint,heading_from_quaternion
                pid=find_game();mem=Memory(pid)
                try:
                    base,_=cached_build(mem,pid)
                    manager=mem.u32(base+0x13c6468);scene=mem.u32(base+0x14641f8)
                    actor=mem.u32(manager+0x24+slot*4)
                    row=actor_record(mem,base,slot,actor,include_dead=True)
                    fingerprint=map_fingerprint(mem,base)
                    if mem.u32(base+0x14641f8)!=scene or mem.u32(manager+0x24+slot*4)!=actor:
                        raise ValueError('Scene changed during position capture.')
                    from board_position_labels import capture_name
                    value=dict(name=capture_name(mem,base,scene),
                               position=list(row['position']),heading_degrees=math.degrees(heading_from_quaternion(row['quaternion'])),
                               map_fingerprint=fingerprint,source_slot=slot)
                finally:mem.close()
                self.messages.put(('bookmark_saved',value))
            except Exception as exc:self.messages.put(('player_action',str(exc)))
        threading.Thread(target=capture,daemon=True).start()

    def teleport_me_to_freecam(self):
        slot=self.me.current()
        if not 0<=slot<8:
            self.show_dialog('error','Teleport me to freecam','Select Who is me first.');return
        try:
            self.submit_action(dict(action='teleport_me_to_freecam',me_slot=slot,slots=[slot],
                                    include_me=True,include_dead=True))
        except queue.Full:self.show_dialog('error','Teleport me to freecam','Action queue is full.')

    def bookmark_items(self):
        session=getattr(self,'_bookmark_session',None)
        if session is not None and session['mode']==self.bookmark_mode:return session['items']
        if self.bookmark_mode=='camera':return self.freecam_positions
        return self.formations if self.bookmark_mode=='formation' else self.bookmarks

    @staticmethod
    def load_saved_positions(path,key,version):
        saved=load_json(path)
        if not isinstance(saved,dict) or not isinstance(saved.get(key),list):return []
        rows=saved[key]
        if saved.get('ordering')!='newest_first':
            rows=list(reversed(rows))
            save_json(path,{**saved,'version':version,key:rows,'ordering':'newest_first'})
        return rows

    def persist_bookmarks(self,mode=None):
        mode=mode or self.bookmark_mode
        session=getattr(self,'_bookmark_session',None)
        if session is not None and session['mode']==mode:return
        if mode=='camera':save_json(FREECAM_POSITIONS_PATH,{'version':3,'cameras':self.freecam_positions,'ordering':'newest_first'})
        elif mode=='formation':save_json(FORMATIONS_PATH,{'version':2,'formations':self.formations,'ordering':'newest_first'})
        else:save_json(BOOKMARKS_PATH,{'version':1,'positions':self.bookmarks,'ordering':'newest_first'})

    def prepend_bookmark(self,mode,row):
        active=self.bookmark_mode==mode and self.bookmark_window is not None and self.bookmark_window.winfo_exists()
        keep_editor=active and self.bookmark_index is not None and not self.commit_bookmark()
        index=self.bookmark_index+1 if keep_editor else 0
        items=self.bookmark_items() if active else (self.freecam_positions if mode=='camera' else self.formations if mode=='formation' else self.bookmarks)
        items.insert(0,row)
        if active:
            session=self._bookmark_session
            session['deleted']=[(i+1,r) for i,r in session['deleted']]
        self.persist_bookmarks(mode)
        if active:self.refresh_bookmarks(index,keep_editor=keep_editor)

    def save_formation_positions(self):
        if self.formation_capture_busy:return
        try:request=self.player_action_request('save_formation')
        except ValueError as exc:self.show_dialog('error','Saved formation',str(exc));return
        self.formation_capture_busy=True
        self.save_formation_button.configure(state='disabled')
        def capture():
            try:
                from re6_transform_backend import cached_build,capture_formation
                pid=find_game();mem=Memory(pid)
                try:
                    base,_=cached_build(mem,pid)
                    scene=mem.u32(base+0x14641f8)
                    value=capture_formation(mem,base,request)
                    from board_position_labels import capture_name
                    value['name']=capture_name(mem,base,scene)
                finally:mem.close()
                self.messages.put(('formation_saved',value))
            except Exception as exc:self.messages.put(('formation_save_error',str(exc)))
        threading.Thread(target=capture,daemon=True).start()

    def restore_formation_positions(self):
        self.open_bookmarks('formation')

    def queue_freecam_command(self,action,row=None):
        try:self.freecam_commands.put_nowait((action,copy.deepcopy(row)))
        except queue.Full:
            self.player_action_status.set(self.translate('A camera restore is still pending.'))

    def save_freecam_position(self):
        self.queue_freecam_command('save')

    def restore_freecam_position(self):
        self.open_bookmarks('camera')

    def repair_freecam(self):
        self.queue_freecam_command('repair')

    def bookmark_title(self):
        return 'Saved freecam positions' if self.bookmark_mode=='camera' else 'Saved formations' if self.bookmark_mode=='formation' else 'Saved positions'

    def bookmark_columns(self):
        columns=('name','x','y','z','heading');labels=('Name','X','Y','Z','Turn (deg)')
        if self.bookmark_mode=='camera':return columns+('pitch','fov'),labels+('Pitch (deg)','FOV')
        return columns,labels

    def bookmark_capture(self,row):
        if self.bookmark_mode!='formation':
            return {'map_fingerprint':row['map_fingerprint'],'positions':{str(self.me.current()):
                dict(position=list(row['position']),heading_degrees=row['heading_degrees'])}}
        try:
            capture=row['capture']
            if not isinstance(capture,dict) or not capture.get('positions'):
                raise ValueError('Save formation positions first.')
            positions=capture['positions']
            if (not isinstance(positions,dict) or not isinstance(capture.get('map_fingerprint'),str)
                    or any(str(slot) not in tuple(str(i) for i in range(8)) for slot in positions)):
                raise ValueError('Saved formation data is invalid; save it again.')
            for point in positions.values():
                if (not isinstance(point,dict) or not isinstance(point.get('position'),list) or len(point['position'])!=3
                        or any(type(v) not in (int,float) or not math.isfinite(v) or abs(v)>=1000000
                               for v in [*point['position'],point.get('heading_degrees')])):
                    raise ValueError('Saved formation data is invalid; save it again.')
            original=row['original_position'];target=row['position']
            angle=row['heading_degrees']-row['original_heading']
            c=math.cos(math.radians(angle));s=math.sin(math.radians(angle))
            updated={}
            for slot,point in positions.items():
                x,y,z=[point['position'][i]-original[i] for i in range(3)]
                updated[slot]=dict(position=[target[0]+x*c+z*s,target[1]+y,target[2]-x*s+z*c],
                                   heading_degrees=point['heading_degrees']+angle)
            return dict(map_fingerprint=capture['map_fingerprint'],positions=updated)
        except (KeyError,TypeError,ValueError,OverflowError):
            raise ValueError('Saved formation data is invalid; save it again.') from None

    def open_bookmarks(self,mode='player'):
        if self.bookmark_window is not None and self.bookmark_window.winfo_exists():
            if self.bookmark_mode==mode:
                self.bookmark_window.deiconify();self.bookmark_window.lift();return
            if not self.close_bookmarks():return
        self.bookmark_mode=mode
        self._bookmark_session={'mode':mode,'items':copy.deepcopy(self.freecam_positions if mode=='camera' else self.formations if mode=='formation' else self.bookmarks),
                                'deleted':[]}
        window=tk.Toplevel(self.root);window.withdraw();self.bookmark_window=window
        window.transient(self.root);window.attributes('-topmost',True)
        window.title(self.translate(self.bookmark_title()))
        body=ttk.Frame(window,padding=10);body.pack(fill='both',expand=True)
        body.columnconfigure(0,weight=1);body.rowconfigure(0,weight=1)
        frame=ttk.Frame(body);frame.grid(row=0,column=0,sticky='nsew')
        columns,labels=self.bookmark_columns()
        self.bookmark_tree=ttk.Treeview(frame,columns=columns,show='headings',height=8,selectmode='browse')
        scroll=ttk.Scrollbar(frame,orient='vertical',command=self.bookmark_tree.yview)
        self.bookmark_tree.configure(yscrollcommand=scroll.set)
        scroll.pack(side='right',fill='y');self.bookmark_tree.pack(side='left',fill='both',expand=True)
        for col,label,width in zip(columns,labels,(350,110,110,110,105,105,85)):
            self.bookmark_tree.heading(col,text=self.translate(label));self.bookmark_tree.column(col,width=width,minwidth=70)
        self.bookmark_tree.bind('<<TreeviewSelect>>',self.select_bookmark)
        self.bookmark_tree.bind('<Double-1>',lambda _e:self.bookmark_editors[0].focus_set())
        edits=ttk.Frame(body);edits.grid(row=1,column=0,sticky='ew',pady=(10,6))
        self.bookmark_values=[tk.StringVar() for _ in columns];self.bookmark_editors=[]
        for i,(label,var) in enumerate(zip(labels,self.bookmark_values)):
            ttk.Label(edits,text=self.translate(label)).grid(row=0,column=i,sticky='w')
            entry=ttk.Entry(edits,textvariable=var,width=34 if i==0 else 9 if mode=='camera' else 12)
            entry.grid(row=1,column=i,sticky='ew',padx=(0,6));edits.columnconfigure(i,weight=1)
            entry.bind('<FocusOut>',lambda _e:self.commit_bookmark())
            entry.bind('<Return>',lambda _e:self.commit_bookmark())
            self.bookmark_editors.append(entry)
        commands=ttk.Frame(body);commands.grid(row=2,column=0,sticky='ew')
        ttk.Button(commands,text='Up',command=lambda:self.reorder_bookmark(-1)).pack(side='left')
        ttk.Button(commands,text='Down',command=lambda:self.reorder_bookmark(1)).pack(side='left',padx=4)
        ttk.Button(commands,text='Delete',command=self.delete_bookmark).pack(side='left',padx=4)
        self.undo_bookmark_button=ttk.Button(commands,text='Undo deletions',command=self.undo_bookmark_deletions,state='disabled')
        self.undo_bookmark_button.pack(side='left',padx=4)
        ttk.Button(commands,text='Restore selected',command=self.restore_bookmark).pack(side='right')
        ttk.Button(commands,text='Restore on next reload',command=self.arm_bookmark).pack(side='right',padx=6)
        self.bookmark_status=LocalizedStatus(self)
        status_label=ttk.Label(body,textvariable=self.bookmark_status,wraplength=760)
        status_label.grid(row=3,column=0,sticky='ew',pady=(6,0))
        command_groups=[[w] for w in commands.pack_slaves()]
        for group in command_groups:group[0].pack_forget()
        commands.pack_propagate(False)
        self.flow_rows.append((commands,command_groups))
        def layout(_event=None):
            if not window.winfo_exists():return
            self.layout_flow_row(commands,command_groups)
            status_label.configure(wraplength=max(200,body.winfo_width()-20))
        commands.bind('<Configure>',layout,add='+')
        self.bookmark_index=None
        self.refresh_bookmarks(0 if self.bookmark_items() else None)
        window.protocol('WM_DELETE_WINDOW',self.close_bookmarks)
        self.apply_language();self.apply_theme();window.update_idletasks()
        sw,sh=window.winfo_screenwidth(),window.winfo_screenheight()
        width=min(sw-40,max(820,body.winfo_reqwidth()+20))
        window.geometry(f'{width}x520');window.update_idletasks();layout();window.update_idletasks()
        fixed=edits.winfo_reqheight()+commands.winfo_reqheight()+status_label.winfo_reqheight()+60
        height=min(sh-80,max(480,fixed+270))
        window.minsize(min(width,700),min(sh-80,fixed+100))
        x=self.root.winfo_rootx()+(self.root.winfo_width()-width)//2
        y=self.root.winfo_rooty()+(self.root.winfo_height()-height)//2
        window.geometry(f'{width}x{height}{x:+d}{y:+d}')
        dark=self.dark_mode.get()
        theme_titlebar(window,dark,'#202226' if dark else '#eeeeef','#e8eaed' if dark else '#25272a')
        window.deiconify();window.update_idletasks();layout();window.update_idletasks()
        window.lift();window.focus_set()
        window.after_idle(lambda:theme_titlebar(window,dark,'#202226' if dark else '#eeeeef',
                                               '#e8eaed' if dark else '#25272a') if window.winfo_exists() else None)

    def refresh_bookmarks(self,index=None,keep_editor=False):
        if self.bookmark_window is None or not self.bookmark_window.winfo_exists():return
        tree=self.bookmark_tree;tree.delete(*tree.get_children())
        for i,row in enumerate(self.bookmark_items()):
            values=(row.get('name',''),*[f'{v:.3f}' for v in row['position']],f"{row['heading_degrees']:.3f}")
            if self.bookmark_mode=='camera':values+=(f"{row['pitch_degrees']:.3f}",f"{row['fov']:.3f}")
            tree.insert('','end',iid=str(i),values=values)
        if keep_editor:
            self.bookmark_index=index
            tree.selection_set(str(index));tree.see('0')
            return
        self.bookmark_index=None
        if index is not None and 0<=index<len(self.bookmark_items()):tree.selection_set(str(index));tree.see(str(index));self.select_bookmark()
        else:
            for var in self.bookmark_values:var.set('')

    def select_bookmark(self,_event=None):
        selected=self.bookmark_tree.selection()
        if not selected:return
        index=int(selected[0])
        if index==self.bookmark_index:return
        if not self.commit_bookmark():
            if self.bookmark_index is not None:self.bookmark_tree.selection_set(str(self.bookmark_index))
            return
        self.bookmark_index=index;row=self.bookmark_items()[index]
        values=[row['name'],*row['position'],row['heading_degrees']]
        if self.bookmark_mode=='camera':values.extend((row['pitch_degrees'],row['fov']))
        for var,value in zip(self.bookmark_values,values):
            var.set(str(value))

    def commit_bookmark(self):
        if self.bookmark_index is None or not 0<=self.bookmark_index<len(self.bookmark_items()):return True
        try:
            values=[float(v.get()) for v in self.bookmark_values[1:]]
            if not all(math.isfinite(v) and abs(v)<1000000 for v in values):raise ValueError()
        except ValueError:
            self.bookmark_status.set('XYZ和朝向必须是有效数字。' if self.language=='zh' else 'XYZ and heading must be finite numbers.');return False
        index=self.bookmark_index;row=self.bookmark_items()[index]
        updated=dict(row,name=self.bookmark_values[0].get(),position=values[:3],heading_degrees=values[3])
        if self.bookmark_mode=='camera':
            updated.update(pitch_degrees=values[4],fov=values[5])
            try:
                from re6_scene_tools import FreecamPositions
                FreecamPositions.values(updated)
            except ValueError as exc:self.bookmark_status.set(self.translate(str(exc)));return False
        if updated!=row:
            self.bookmark_items()[index]=updated;self.persist_bookmarks()
            self.bookmark_tree.item(str(index),values=(updated['name'],*[f'{v:.3f}' for v in values]))
        self.bookmark_status.set('');return True

    def reorder_bookmark(self,direction):
        if not self.commit_bookmark() or self.bookmark_index is None:return
        before=self.bookmark_index;after=before+direction
        items=self.bookmark_items()
        if not 0<=after<len(items):return
        items[before],items[after]=items[after],items[before]
        self.persist_bookmarks();self.refresh_bookmarks(after)

    def delete_bookmark(self):
        if self.bookmark_index is None or not self.commit_bookmark():return
        items=self.bookmark_items();index=self.bookmark_index
        self._bookmark_session['deleted'].append((index,items.pop(index)))
        self.bookmark_index=None
        self.undo_bookmark_button.configure(state='normal')
        self.refresh_bookmarks(min(index,len(items)-1) if items else None)

    def undo_bookmark_deletions(self):
        session=getattr(self,'_bookmark_session',None)
        if not session or not session['deleted'] or not self.commit_bookmark():return
        items=session['items'];count=len(session['deleted']);index=0
        for index,row in reversed(session['deleted']):items.insert(min(index,len(items)),row)
        session['deleted'].clear()
        self.undo_bookmark_button.configure(state='disabled')
        self.refresh_bookmarks(min(index,len(items)-1))
        self.bookmark_status.set(f'已恢复本次删除的全部 {count} 条记录。' if self.language=='zh' else
                                 f'Restored all {count} records deleted in this window.')

    def close_bookmarks(self):
        session=getattr(self,'_bookmark_session',None)
        if session is None:return True
        if not self.commit_bookmark():return False
        mode=session['mode'];items=session['items']
        try:
            save_json(FREECAM_POSITIONS_PATH if mode=='camera' else FORMATIONS_PATH if mode=='formation' else BOOKMARKS_PATH,
                      {'version':3 if mode=='camera' else 2 if mode=='formation' else 1,
                       'cameras' if mode=='camera' else 'formations' if mode=='formation' else 'positions':items,'ordering':'newest_first'})
        except OSError as exc:
            self.bookmark_status.set(str(exc));return False
        if mode=='camera':self.freecam_positions=items
        elif mode=='formation':self.formations=items
        else:self.bookmarks=items
        self._bookmark_session=None;self.bookmark_index=None
        self.bookmark_window.destroy();self.bookmark_window=None
        return True

    def restore_bookmark(self):
        if not self.commit_bookmark() or self.bookmark_index is None:return
        slot=self.me.current();row=self.bookmark_items()[self.bookmark_index]
        if self.bookmark_mode=='camera':self.queue_freecam_command('restore',row);return
        if not 0<=slot<8:return
        try:
            capture=self.bookmark_capture(row)
            self.submit_action(dict(action='restore_positions',me_slot=slot,slots=sorted(int(s) for s in capture['positions']),include_me=True,include_dead=True,capture=capture))
            self.bookmark_status.set('已提交位置与朝向。' if self.language=='zh' else 'Position and heading submitted.')
        except (ValueError,queue.Full) as exc:self.bookmark_status.set(str(exc))

    def arm_bookmark(self):
        if not self.commit_bookmark() or self.bookmark_index is None:return
        slot=self.me.current();row=self.bookmark_items()[self.bookmark_index]
        if self.bookmark_mode=='camera':self.queue_freecam_command('arm',row);return
        if not 0<=slot<8:return
        try:
            self.configuration()
            capture=dict(self.bookmark_capture(row),enabled=True)
            save_json(RESPAWN_PATH,capture)
            if any(str(s)!=str(slot) for s in capture['positions']):self.ai_plan.set(True)
            self.game_default_positions.set(False);self.restore_capture.set(True)
            self.arm()
            self.bookmark_status.set('Captured positions are armed for the next reload.')
        except (ValueError,OSError) as exc:self.bookmark_status.set(str(exc))

    def model_repair_maintenance(self):
        """Renew camera repair independently of scene locks and queued commands."""
        from freecam_model_repair import FreecamModelRepair
        repair=FreecamModelRepair();last_state=None;last_error=None
        try:
            while not self.monitor_stop.is_set():
                try:
                    repair.poll(self.model_repair_switch)
                    last_error=None
                except Exception as exc:
                    error=str(exc)
                    if error!=last_error:
                        self.messages.put(('log','Model culling repair: '+error))
                        last_error=error
                if last_state is not repair.active:
                    self.messages.put(('model_repair_state',repair.active))
                    last_state=repair.active
                self.monitor_stop.wait(.1)
        finally:
            try:repair.close()
            except Exception as exc:self.messages.put(('log','Model culling repair cleanup: '+str(exc)))
            self.messages.put(('model_repair_state',False))

    def scene_maintenance(self):
        from board_motion_diagnostics import start as start_motion_diagnostics
        start_motion_diagnostics(self)
        from re6_scene_tools import SceneController,GameTopmost,FreecamInputGate,FreecamPositions
        from enemy_visibility import SelectedEnemyVisibility
        from freecam_input_monitor import FreecamInputMonitor
        from re6_blood_filter import PlayerBloodFilter
        def make_helpers():
            controller=SceneController(BOARD_LOG_ROOT/'scene_tools')
            controller.request_player_lock(self.player_lock_enabled)
            controller.folder.mkdir(exist_ok=True)
            return controller,GameTopmost(),SelectedEnemyVisibility(),FreecamInputGate(),FreecamPositions(),PlayerBloodFilter()

        controller,topmost,visibility,freecam,camera,blood=make_helpers()
        input_monitor=FreecamInputMonitor()
        last_epoch=0;last_status=None;last_error=None;last_pause_error=None
        switch_states={}
        bound_identity=None
        last_probe=0.0
        process_wait_announced=False

        def process_identity():
            """Return (pid, creation time), or None while BH6 is absent/unstable."""
            mem=None
            try:
                pid=find_game()
                mem=Memory(pid)
                if not mem.alive():return None
                return (pid,mem.creation)
            except (OSError,RuntimeError,ValueError):
                return None
            finally:
                if mem is not None:mem.close()

        def close_helpers():
            # A dead process has already discarded its hooks. Cleanup is best effort;
            # never let stale native state stop the reconnect loop.
            for helper in (camera,freecam,visibility,blood):
                try:helper.close()
                except Exception as exc:self.messages.put(('log','Scene helper cleanup: '+str(exc)))
            try:topmost.close()
            except Exception:pass
            deadline=time.monotonic()+2
            while True:
                try:controller.close();break
                except Exception as exc:
                    if time.monotonic()>=deadline:
                        self.messages.put(('log','Scene controller cleanup: '+str(exc)));break
                    time.sleep(.05)

        def rebuild_helpers():
            nonlocal controller,topmost,visibility,freecam,camera,blood
            controller,topmost,visibility,freecam,camera,blood=make_helpers()
        try:
            while not self.monitor_stop.is_set():
                # Bind native helpers to the current process identity. This also
                # handles BH6 being closed and launched again without restarting Board.
                now=time.monotonic()
                if now>=last_probe:
                    current=process_identity();last_probe=now+.5
                    if current is None:
                        if bound_identity is not None:
                            self.messages.put(('log','BH6 process lost; waiting for a new process.'))
                            close_helpers();rebuild_helpers()
                            bound_identity=None;switch_states={};last_status=None;last_error=None
                        elif not process_wait_announced:
                            self.messages.put(('log','BH6 process not found; waiting to attach automatically.'))
                            process_wait_announced=True
                        self.monitor_stop.wait(.25)
                        continue
                    if current!=bound_identity:
                        if bound_identity is not None:
                            close_helpers();rebuild_helpers()
                            self.messages.put(('log',f'BH6 process reconnected (PID {current[0]}).'))
                        else:
                            self.messages.put(('log',f'BH6 process attached (PID {current[0]}).'))
                        bound_identity=current;process_wait_announced=False
                        switch_states={};last_status=None;last_error=None;last_pause_error=None

                input_error=input_monitor.poll(camera)
                if input_error is not None:self.messages.put(('freecam_input_error',input_error))
                try:
                    result=camera.poll()
                    if result:
                        self.messages.put(('freecam_result',result))
                        self.messages.put(('log',f"Freecam reload FOV: before={result.get('before_fov')!r}, after={result.get('after_fov')!r}, restored={result.get('restored_fov')!r}"))
                except Exception:pass
                while not self.freecam_commands.empty():
                    try:action,row=self.freecam_commands.get_nowait()
                    except queue.Empty:break
                    try:
                        if action=='save':
                            value=camera.capture()
                            from board_position_labels import capture_name
                            value['name']=capture_name(camera.p,camera.base,value['scene'])
                            self.messages.put(('freecam_saved',value))
                            continue
                        if action=='restore':
                            repair_result=camera.restore(row)
                            self.messages.put(('freecam_result',{'message':'Freecam position and angles restored; reload FOV repair applied.',
                                **repair_result}))
                            continue
                        elif action=='arm':camera.arm(row)
                        elif action=='repair':
                            repair_result=camera.repair_ct()
                            self.messages.put(('freecam_result',{'message':('已恢复自由相机视野。' if self.language=='zh' else 'Freecam field of view restored.'),
                                **repair_result}))
                            continue
                        self.messages.put(('freecam_result',{'message':'Camera restore armed for the next reload.' if action=='arm' else 'Freecam position, angles and FOV restored.'}))
                    except Exception as exc:self.messages.put(('freecam_result',{'error':str(exc)}))
                for name,helper,enabled in (('visibility',visibility,self.enemies_hidden),
                                           ('blood',blood,self.players_no_bleeding),
                                           ('freecam',freecam,self.freecam_input_paused)):
                    try:
                        receipt=None
                        if name=='visibility':helper.apply(enabled,selection=self.visibility_selection)
                        else:receipt=helper.apply(enabled)
                        state=(enabled,None)
                        if name=='blood' and receipt:
                            state+=(bool(receipt.get('native_calls')),bool(receipt.get('hidden_draws')))
                    except Exception as exc:
                        error=('Reload the updated Freecam CT and enable Cam Control Script first.'
                               if name=='freecam' and isinstance(exc,FileNotFoundError) else str(exc))
                        state=(enabled,error)
                    if switch_states.get(name)!=state:
                        self.messages.put(('scene_switch',{'name':name,'enabled':enabled,'error':state[1],
                            'receipt':receipt if name=='blood' and state[1] is None else None}))
                        switch_states[name]=state
                try:
                    guard=self.grab_pause_guard
                    epoch=self.grab_action_epoch
                    if guard is not None:
                        pause_result=guard.reconcile_pause()
                        if pause_result:self.messages.put(('grab_pause',{**pause_result,'epoch':epoch}))
                    last_pause_error=None
                except Exception as exc:
                    error=str(exc)
                    if error!=last_pause_error:
                        self.messages.put(('grab_pause',{'error':error,'paused':False,'epoch':epoch}))
                        last_pause_error=error
                if bound_identity is not None:
                    try:
                        topmost.apply(self.game_topmost_enabled)
                        epoch=self.scene_repair_epoch
                        with self.enemy_ai_lock:
                            player_lock=(self.player_lock_enabled and not self.enemy_idle_enabled
                                         and self.idle_released.is_set())
                            if player_lock:self.player_lock_released.clear()
                            result=controller.poll(self.enemy_lock_enabled,repair=epoch!=last_epoch,
                                                   prone_slots=self.prone_slots,player_lock=player_lock,
                                                   enemy_facing=getattr(self,'enemy_lock_facing',True),
                                                   player_facing=getattr(self,'player_lock_facing',True),
                                                   enemy_periodic_restore=getattr(self,'enemy_periodic_restore',False),
                                                   player_periodic_restore=getattr(self,'player_periodic_restore',False))
                            if not player_lock:self.player_lock_released.set()
                        if result.get('lock_restored'):
                            self.messages.put(('log',('定期恢复：已重新应用 %d 个偏移对象的锁定基线。' if self.language=='zh'
                                else 'Periodic restore: reapplied lock baselines for %d displaced actors.')%result['lock_restored']))
                        last_epoch=epoch
                        signature=(result['scene'],result['locked'],result['repaired'],result['pending'],
                                   self.enemy_lock_enabled,self.player_lock_enabled,self.game_topmost_enabled)
                        if signature!=last_status:
                            self.messages.put(('scene_tools',{**result,'topmost':self.game_topmost_enabled}))
                            last_status=signature
                        last_error=None
                    except Exception as exc:
                        error=type(exc).__name__+': '+str(exc)[:240]
                        if 'Another Board native operation' not in error and error!=last_error:
                            self.messages.put(('scene_tools',{'error':error}))
                            last_error=error
                        if any(marker in error for marker in ('stop was not acknowledged','ReadProcessMemory','Scene is unavailable','Game window is unavailable')):
                            # The identity probe above will release stale helpers and
                            # reconnect when BH6 returns; keep this loop alive meanwhile.
                            self.messages.put(('scene_tools',{'error':'Scene unavailable; waiting for automatic reconnect.'}))
                self.monitor_stop.wait(.5)
        finally:
            for helper in (camera,freecam,visibility,blood):
                try:helper.close()
                except Exception as exc:self.messages.put(('log',str(exc)))
            try:topmost.close()
            except OSError:pass
            deadline=time.monotonic()+10
            while True:
                try:controller.close();break
                except Exception as exc:
                    if time.monotonic()>=deadline:
                        self.messages.put(('log','Scene helper cleanup: '+str(exc)));break
                    time.sleep(.1)

    def toggle_grab_pause(self, enabled=None):
        with self.grab_toggle_lock:
            enabled=not self.grab_pause_requested if enabled is None else bool(enabled)
            self.grab_pause_requested=enabled
            self.grab_action_epoch+=1
        # An explicit stop also supersedes the complex page's one-time default.
        self._grab_pause_explicitly_disabled=not enabled
        if not enabled:
            runtime=getattr(self,'animation_complex_runtime',None)
            if runtime is not None:
                runtime.cancel_deliveries()
                runtime.cancel_releases()
        self.grab_resume_stage='idle'
        self.pause_attack_button.configure(state='normal')
        self.random_resume_button.configure(state='disabled')
        def apply(previous):
            # QTE buttons share grab_pause_thread. Drain their setup before the
            # explicit toggle so a late setup cannot arm protection afterwards.
            if previous is not None and previous.is_alive():previous.join()
            while True:
                with self.grab_toggle_lock:
                    wanted=self.grab_pause_requested
                    current_epoch=self.grab_action_epoch
                try:
                    if self.grab_pause_guard is None:
                        from re6_transform_backend import GrabPauseController
                        self.grab_pause_guard=GrabPauseController()
                    result=self.grab_pause_guard.set_paused(wanted)
                    receipt={**result,'paused':wanted,'epoch':current_epoch}
                except Exception as exc:
                    receipt={'error':str(exc),'epoch':current_epoch}
                with self.grab_toggle_lock:
                    if current_epoch!=self.grab_action_epoch:continue
                    self.grab_pause_thread=None
                    self.grab_toggle_thread=None
                    self.messages.put(('grab_pause',receipt))
                    return
        with self.grab_toggle_lock:
            if self.grab_toggle_thread is not None:return
            previous=self.grab_pause_thread
            self.grab_toggle_thread=threading.Thread(target=apply,args=(previous,),daemon=True)
            self.grab_pause_thread=self.grab_toggle_thread
            self.grab_toggle_thread.start()

    def update_grab_buttons(self):
        releasing=self.grab_resume_stage in ('qte','native')
        busy=self.grab_resume_stage in ('waiting','qte','native')
        self.grab_paused=self.grab_pause_requested and not releasing
        self.pause_attack_button.configure(state='normal',text=self.translate('Allow enemies to kill players' if self.grab_paused else 'Prevent enemies from killing players'))
        self.random_resume_button.configure(state='disabled' if busy else 'normal')
        self.qte_success_button.configure(state='disabled' if busy else 'normal')
        self.delayed_qte_success_button.configure(state='disabled' if busy else 'normal')
        self.update_qte_probability_label()

