    def _qte_timeline_points(self):
        value=getattr(self,'delayed_qte_timeline',None)
        try:
            return normalize_qte_timeline(value) if value is not None else qte_timeline_from_legacy(self)
        except ValueError:
            return qte_timeline_from_legacy(self)

    @staticmethod
    def _qte_backup_rows():
        payload=load_json(DELAYED_QTE_BACKUPS_PATH,{})
        rows=payload.get('backups',[]) if isinstance(payload,dict) else []
        result=[]
        for row in rows:
            if not isinstance(row,dict):continue
            points=row.get('points',row.get('grid'))
            if isinstance(points,list) and len(points)==8 and all(isinstance(x,list) and len(x)==8 for x in points):
                points=[next((r for r,v in enumerate(col) if v),None) for col in zip(*points)]
            try:points=normalize_qte_timeline(points)
            except (TypeError,ValueError):continue
            try:
                low=float(row.get('low',.1));high=float(row.get('high',.6))
                if not all(math.isfinite(v) and 0<=v<=10 for v in (low,high)) or high<low:continue
            except (TypeError,ValueError):continue
            result.append({'id':str(row.get('id',time.time_ns())),'name':str(row.get('name','')) or 'Backup',
                           'points':points,'low':low,'high':high,'preset':str(row.get('preset','custom'))})
        return result

