        tree.grid(row=0,column=0,sticky='nsew');scroll=ttk.Scrollbar(body,orient='vertical',command=tree.yview);scroll.grid(row=0,column=1,sticky='ns');tree.configure(yscrollcommand=scroll.set)
        for i,row in enumerate(rows):tree.insert('', 'end',iid=str(i),values=(row['name'],f"{row['low']:g}..{row['high']:g}",sum(v is not None for v in row['points'])))
        tree.selection_set('0');error2=tk.StringVar();ttk.Label(body,textvariable=error2,foreground='#d65252',wraplength=430).grid(row=1,column=0,columnspan=2,sticky='ew',pady=(6,0))
        def apply():
            selected=tree.selection()
            if not selected:return
            row=rows[int(selected[0])];points[:]=row['points'];low.set(f"{row['low']:g}");high.set(f"{row['high']:g}");preset.set(row.get('preset','custom'))
            preset_box.current(preset_keys.index(preset.get()) if preset.get() in preset_keys else 0);chart.low=low.get();chart.high=high.get();chart.redraw();popup.destroy()
        commands=ttk.Frame(body);commands.grid(row=2,column=0,columnspan=2,sticky='ew',pady=(8,0));ttk.Button(commands,text=self.translate('Cancel'),command=popup.destroy).pack(side='right',padx=4);ttk.Button(commands,text=self.translate('Apply'),command=apply).pack(side='right')
        popup.update_idletasks();self._show_qte_timeline_window(popup,560,420)


