    def open_visibility_assignment(self):
        existing=self.visibility_window
        if existing is not None and existing.winfo_exists():existing.destroy()
        window=tk.Toplevel(self.root);window.withdraw();self.visibility_window=window
        window.title(self.translate('Enemy visibility assignments'));window.transient(self.root)
        window.geometry('670x480');window.minsize(430,260)
