_transform_observation_source = r'''
def check_transform_code(m, base):
    """Observe entry bytes without rejecting native transform requests."""
    import board_diagnostics as diagnostics
    issues = []
    signatures = {
        0x635d30: '8b442404d9000f57c0d95950',
        0x635d60: '8b442404d9000f57c0568bf1d95e50',
        0x64f1f0: '558bec83e4f083ec4c568bf1',
        0x54a4b0: '568bf1e85834ceff',
        0xb9ff60: '558bec83e4f083ec4c56',
        0xb9f430: '558bec83e4f083ec740f57c953568bf1',
        0x22e7d0: '8b442404d9000f57c0',
        0x371260: 'c6413b00e9',
        0x53e3c0: '558bec83e4f083ec14',
        0x53ec50: '83ec205356',
    }
    signatures.update(globals().get('_native_transform_extra_signatures', {}))
    for rva, sig in signatures.items():
        try:
            actual = m.read(base + rva, len(bytes.fromhex(sig))).hex()
        except Exception as exc:
            issues.append(dict(rva=hex(rva), expected=sig, read_error=str(exc)))
        else:
            if actual != sig:
                issues.append(dict(rva=hex(rva), expected=sig, actual=actual))
    if issues:
        try:
            diagnostics.event('native_transform_signature_observation', dict(
                mode='observe_only', decision='continue',
                pid=getattr(m, 'pid', None), base=hex(base), entries=issues),
                durable=True)
        except Exception:
            # A diagnostic sink failure must not become an operation gate.
            pass
'''

_scene_observation_source = '\n_native_transform_extra_signatures = SIGNATURES\n' + _transform_observation_source

del _scene_observation_source

del _transform_observation_source

def _transform_repair_BoardApp_submit_action(self, request):
    from board_transform_repairs import audit
    request.setdefault('_input_at',time.monotonic())
    request.setdefault('_input_id',time.monotonic_ns())
    audit('input_queued',request_id=request['_input_id'],action=request.get('action'),
          held=self._building_hold is not None,depth=self.player_actions.qsize(),
          players=request.get('slots'),enemies=len(request.get('enemy_selection',())))
    y_axis=getattr(getattr(self,'window_controls',None),'y_axis',None)
    if request.pop('_board_y_axis',False) and y_axis is not None and y_axis.submit_board_move(request,self._building_hold):return
    if request.get('auto_rotation') and 'rotation_layers' not in request:
        request=self.enemy_queue.rotation.effective() or request
    if request.get('action') in ('rotate','rotate_formation') and 'enemy_selection' not in request and 'rotation_layers' not in request:
        request['player_camera_static']=bool(self.player_camera_static.get())
        request['visual_only_rotation']=request['action']=='rotate' and bool(self.visual_only_rotation.get())
    held = self._building_hold
    if held is not None:
        request['_held'] = held
    try:
        previous=self.enemy_action_cancel
        if request.get('action') in ('hunt_players','scatter_em4700'):
            request['_cancel']=threading.Event()
        releases_idle=(request.get('action')=='hunt_players' or
                       (request.get('action')=='scatter_em4700' and request.get('interaction_mode','contact')=='contact'))
        was_idle=self.enemy_idle_enabled
        if releases_idle:self.set_enemy_idle(False)
        try:self.player_actions.put_nowait(request)
        except queue.Full:
            if releases_idle and was_idle:self.set_enemy_idle(True)
            raise
        if previous is not None and releases_idle:previous.set()
        if '_cancel' in request:self.enemy_action_cancel=request['_cancel']
    except queue.Full:
        raise

BoardApp.submit_action = _transform_repair_BoardApp_submit_action

def _transform_repair_BoardApp_player_action_writer(self):
    """Serialize actions through one persistent native game-thread controller."""
    from contextlib import nullcontext
    from re6_transform_backend import run_action
    from board_hunt_xyz import HuntService,format_status as xyz_status
    from visual_rotation import DisplayService
    from board_enemy_queue import controller_type
    from board_enemy_rotation import controller_type as rotation_controller_type
    LiveTransformController=rotation_controller_type(controller_type())
    display_service=DisplayService(lambda:getattr(self,'standing_pose_request',None),
        lambda detail:self.messages.put(('log',detail)),
        rotation_getter=self.enemy_queue.rotation.effective,rotation_error=self.enemy_queue.rotation.failed)
    controller=None; controller_dir=None; active=None; last_notice=0.0
