    enemy_worker=Coordinator(self,Path(__file__).resolve(),WORKER_PYTHON,new_log_batch)
    deferred_request=None;process_resume=None;em4701_sent_revision=-1
    auto_retry_at=0.0;last_auto_error=None;held_retry=None;hold_retry_at=0.0

    cleanup_pending=False

    def teleport_notice(request, text, terminal=False):
        if request is None or request.get('action')!='scatter_em4700':return
        if terminal:request['_teleport_finished']=True
        self.messages.put(('teleport_status',dict(token=request.get('_teleport_token'),text=text)))

    def close_controller(strict=False):
        nonlocal controller,controller_dir,active,cleanup_pending
        if controller is not None:
            try:
                controller.close()
            except Exception as exc:
                # Retain ownership until cleanup succeeds. Dropping this
                # controller would leak its hook and operation mutex.
                self.messages.put(('log','Native controller cleanup: '+str(exc)))
                cleanup_pending=True;active=None
                if strict:raise
                return False
            if controller_dir is not None:
                try:
                    save_json(controller_dir/'complete.json',{'state':'controller_closed'})
                    prune_log_batches()
                except OSError as exc:self.messages.put(('log','Controller log cleanup: '+str(exc)))
        controller=None; controller_dir=None; active=None;cleanup_pending=False
        return True

