exec(compile('"""Bounded public updater; imported only after the board has defined its UI."""\nimport hashlib, json, os, pathlib, queue, re, shutil, threading, time, urllib.parse, urllib.request\nREPOSITORY = \'GPT-6-RE6-Trainer/GPT-6-RE6-Trainer\' # Single repository configuration point.\nNAMES = (\'GPT-6 RE6 Cheat Board.py\', \'RE6 NO Game over + No Blur .CT\')\nCURRENT_VERSION = 1\nMAX_SIZE = 64 * 1024 * 1024\nBASELINE_GIT_SHA1 = {NAMES[1]: \'2eb19cb07ec190e36319de1619c7fe762d0eb14b\'}\nclass UpdateError(Exception): pass\n\ndef git_blob_sha1(data):\n    return hashlib.sha1(b\'blob \'+str(len(data)).encode(\'ascii\')+b\'\\0\'+data).hexdigest()\n\ndef safe_url(url):\n    p=urllib.parse.urlsplit(url)\n    path=urllib.parse.unquote(p.path)\n    if p.hostname==\'api.github.com\' and p.scheme==\'https\' and not p.username and not p.password and p.port in (None,443) and p.path==\'/repos/\'+REPOSITORY+\'/git/trees/main\' and p.query==\'recursive=1\' and not p.fragment: return url\n    if p.scheme!=\'https\' or p.username or p.password or p.port not in (None,443) or p.query or p.fragment or \'\\\\\' in path or any(x in (\'.\',\'..\') for x in path.split(\'/\')):\n        raise UpdateError(\'Unsafe update URL\')\n    prefix=\'/\' + REPOSITORY + \'/\'\n    if p.hostname==\'raw.githubusercontent.com\' and path.startswith(prefix): return url\n    if p.hostname==\'github.com\' and path.startswith(prefix+\'releases/\'): return url\n    raise UpdateError(\'Unexpected update host or repository\')\nclass Redirects(urllib.request.HTTPRedirectHandler):\n    def redirect_request(self, req, fp, code, msg, headers, newurl):\n        safe_url(newurl)\n        return super().redirect_request(req,fp,code,msg,headers,newurl)\ndef fetch(url, limit, sink=None, opener=None):\n    safe_url(url)\n    accept=\'application/vnd.github+json\' if urllib.parse.urlsplit(url).hostname==\'api.github.com\' else \'application/octet-stream\'\n    request=urllib.request.Request(url,headers={\'User-Agent\':\'RE6-Board-Updater/1\',\'Accept\':accept})\n    client=opener or urllib.request.build_opener(Redirects())\n    with client.open(request,timeout=12) as response:\n        safe_url(response.geturl())\n        length=response.headers.get(\'Content-Length\')\n        if length is not None and (not length.isdigit() or int(length)>limit): raise UpdateError(\'Invalid download length\')\n        data=bytearray(); count=0; digest=hashlib.sha256(); deadline=time.monotonic()+90\n        while True:\n            if time.monotonic()>deadline: raise UpdateError(\'Download timeout\')\n            chunk=response.read(min(65536,limit-count+1))\n            if not chunk: break\n            count+=len(chunk)\n            if count>limit: raise UpdateError(\'Download too large\')\n            digest.update(chunk)\n            if sink is None: data.extend(chunk)\n            else: sink.write(chunk)\n        if length is not None and count!=int(length): raise UpdateError(\'Incomplete download\')\n        return bytes(data),count,digest.hexdigest()\ndef parse_manifest(data):\n    obj=json.loads(data)\n    if obj.get(\'schema\')!=1 or obj.get(\'repository_configured\') is not True: raise UpdateError(\'Unpublished manifest\')\n    files=obj.get(\'files\')\n    if not isinstance(files,list) or len(files)>64: raise UpdateError(\'Invalid file list\')\n    result=[]; seen=set()\n    for entry in files:\n        name=entry.get(\'name\')\n        if name not in NAMES: continue\n        if name in seen: raise UpdateError(\'Duplicate update\')\n        seen.add(name)\n        if entry.get(\'placeholder\') is not False: continue\n        version=entry.get(\'version\'); size=entry.get(\'size\'); digest=entry.get(\'sha256\')\n        if type(version) is not int or version<=CURRENT_VERSION: continue\n        if type(size) is not int or not 1<=size<=MAX_SIZE or not isinstance(digest,str) or not re.fullmatch(\'[0-9a-f]{64}\',digest): raise UpdateError(\'Invalid file metadata\')\n        safe_url(entry.get(\'url\',\'\'))\n        if pathlib.PurePosixPath(urllib.parse.unquote(urllib.parse.urlsplit(entry[\'url\']).path)).name!=name: raise UpdateError(\'Filename mismatch\')\n        result.append(dict(entry))\n    return result\n\ndef discover():\n    # Git blob fingerprints detect source changes without requiring a version bump.\n    data,_,_=fetch(\'https://api.github.com/repos/\'+REPOSITORY+\'/git/trees/main?recursive=1\',2*1024*1024)\n    tree=json.loads(data)\n    if tree.get(\'truncated\') is not False or not isinstance(tree.get(\'tree\'),list): raise UpdateError(\'Incomplete repository tree\')\n    entries={}\n    for node in tree[\'tree\']:\n        path=node.get(\'path\',\'\')\n        if node.get(\'type\')!=\'blob\' or not isinstance(path,str) or len(path)>=1024: continue\n        if any(x in (\'\',\'.\', \'..\') for x in path.split(\'/\')) or \'\\\\\' in path: continue\n        name=pathlib.PurePosixPath(path).name\n        if name not in NAMES: continue\n        size=node.get(\'size\'); digest=node.get(\'sha\')\n        if type(size) is not int or not 1<=size<=MAX_SIZE or not isinstance(digest,str) or not re.fullmatch(\'[0-9a-f]{40}\',digest):\n            raise UpdateError(\'Invalid repository file metadata\')\n        url=\'https://raw.githubusercontent.com/\'+REPOSITORY+\'/main/\'+urllib.parse.quote(path,safe=\'/\')\n        entry=dict(name=name,version=CURRENT_VERSION,size=size,git_sha1=digest,url=url,placeholder=False)\n        old=entries.get(name)\n        if old is not None and old[\'git_sha1\']!=digest: raise UpdateError(\'Conflicting repository files\')\n        if old is None: entries[name]=entry\n    return list(entries.values())\n\ndef local_path(directory,name,script_path=None):\n    directory=pathlib.Path(directory)\n    if name==NAMES[0] and script_path is not None:\n        script_path=pathlib.Path(script_path)\n        if script_path.parent.resolve()!=directory.resolve() or script_path.suffix.lower()!=\'.py\': raise UpdateError(\'Invalid running script path\')\n        return directory/script_path.name\n    target=directory/name\n    alias=directory/name.replace(\' \',\'.\') # GitHub normalizes release attachment spaces.\n    return alias if not target.exists() and not target.is_symlink() and (alias.exists() or alias.is_symlink()) else target\n\ndef select_updates(entries,directory,script_path=None):\n    directory=pathlib.Path(directory)\n    result=[]\n    for entry in entries:\n        path=local_path(directory,entry[\'name\'],script_path)\n        if path.is_symlink(): raise UpdateError(\'Unsafe local update target\')\n        if path.is_file() and path.stat().st_size==entry[\'size\']:\n            data=path.read_bytes()\n            if entry.get(\'git_sha1\'):\n                if git_blob_sha1(data)==entry[\'git_sha1\']: continue\n            elif hashlib.sha256(data).hexdigest()==entry[\'sha256\']: continue\n        elif not path.exists() and BASELINE_GIT_SHA1.get(entry[\'name\'])==entry.get(\'git_sha1\') and entry.get(\'git_sha1\'):\n            continue # The unchanged companion CT may live outside the trainer folder.\n        result.append(entry)\n    return result\n\ndef stage(entry, directory, opener=None, script_path=None):\n    entry=dict(entry)\n    directory=pathlib.Path(directory).resolve(); name=entry[\'name\']\n    if name not in NAMES: raise UpdateError(\'Invalid target\')\n    target=local_path(directory,name,script_path); new=target.with_name(target.name+\'NEW\')\n    if target.is_symlink() or new.exists() or new.is_symlink(): raise UpdateError(\'Unsafe or occupied update path\')\n    try:\n        with new.open(\'xb\') as output:\n            _,size,digest=fetch(entry[\'url\'],entry[\'size\'],output,opener)\n            output.flush(); os.fsync(output.fileno())\n        payload=new.read_bytes()\n        if size!=entry[\'size\'] or (entry.get(\'sha256\') and digest!=entry[\'sha256\']): raise UpdateError(\'Checksum mismatch\')\n        if entry.get(\'git_sha1\') and git_blob_sha1(payload)!=entry[\'git_sha1\']: raise UpdateError(\'Repository fingerprint mismatch\')\n        if not entry.get(\'sha256\') and not entry.get(\'git_sha1\'): raise UpdateError(\'Missing download fingerprint\')\n        entry[\'sha256\']=digest\n        head=payload[:4096]\n        if b\'PLACEHOLDER\' in head.upper(): raise UpdateError(\'Placeholder payload\')\n        if name.endswith(\'.py\'):\n            compile(new.read_bytes(),name,\'exec\')\n        else:\n            import xml.etree.ElementTree as ET\n            if ET.parse(new).getroot().tag!=\'CheatTable\': raise UpdateError(\'Invalid CT payload\')\n        return (target,new,entry)\n    except BaseException:\n        new.unlink(missing_ok=True)\n        raise\n\ndef apply_staged(item):\n    target,new,entry=item\n    if new.is_symlink() or target.is_symlink(): raise UpdateError(\'Unsafe target\')\n    data=new.read_bytes()\n    if len(data)!=entry[\'size\'] or hashlib.sha256(data).hexdigest()!=entry[\'sha256\']: raise UpdateError(\'Staged file changed\')\n    backup=target.with_name(target.name+\'.rollback\')\n    if backup.is_symlink(): raise UpdateError(\'Unsafe rollback\')\n    if target.exists():\n        temp=backup.with_name(backup.name+\'.tmp\')\n        if temp.exists() or temp.is_symlink(): raise UpdateError(\'Occupied rollback path\')\n        try:\n            with target.open(\'rb\') as source, temp.open(\'xb\') as out:\n                shutil.copyfileobj(source,out); out.flush(); os.fsync(out.fileno())\n            os.replace(temp,backup)\n        finally: temp.unlink(missing_ok=True)\n    os.replace(new,target) # Failure (including CT lock) leaves the original target intact.\n    state_path=target.parent/\'.re6-update-versions.json\'\n    try:\n        versions=json.loads(state_path.read_text(encoding=\'utf-8\')) if state_path.stat().st_size<4096 else {}\n    except Exception:versions={}\n    if not isinstance(versions,dict):versions={}\n    versions={k:v for k,v in versions.items() if k in NAMES and type(v) is int}\n    versions[target.name]=entry[\'version\']\n    state_new=state_path.with_name(state_path.name+\'.tmp\')\n    if state_path.is_symlink() or state_new.exists() or state_new.is_symlink():return\n    try:\n        with state_new.open(\'x\',encoding=\'utf-8\') as out:\n            json.dump(versions,out);out.flush();os.fsync(out.fileno())\n        os.replace(state_new,state_path)\n    finally:state_new.unlink(missing_ok=True)\n\ndef install(namespace):\n    tk=namespace[\'tk\']; ttk=namespace[\'ttk\']; BoardApp=namespace[\'BoardApp\']\n    script_path=pathlib.Path(namespace[\'__file__\']).absolute(); directory=script_path.parent.resolve(); script_path=directory/script_path.name\n    original_init=BoardApp.__init__; original_gui=namespace[\'run_gui\']; state={\'pending\':[],\'app\':None}\n    class Controller:\n        def __init__(self,app):\n            self.app=app; self.events=queue.Queue(); self.busy=False\n            app.root.after(1800,lambda:self.check(False)); app.root.after(200,self.poll)\n        def text(self,zh,en): return zh if self.app.language==\'zh\' else en\n        def check(self,manual):\n            if self.busy or self.app._closing:return\n            self.busy=True\n            def work():\n                try:\n                    entries=select_updates(discover(),directory,script_path)\n                    self.events.put((\'checked\',entries,manual))\n                except Exception:self.events.put((\'failed\',None,manual))\n            threading.Thread(target=work,daemon=True).start()\n        def poll(self):\n            if self.app._closing:return\n            try:\n                while True:\n                    kind,value,manual=self.events.get_nowait(); self.busy=False\n                    if kind==\'checked\' and value:self.dialog(value)\n                    elif kind==\'ready\':\n                        state[\'pending\']=value; self.app.close()\n                        if not getattr(self.app,\'_closing\',False):\n                            state[\'pending\']=[]\n                            for _,new,_ in value:\n                                try:new.unlink(missing_ok=True)\n                                except OSError:pass\n                        else:return\n                    elif manual:\n                        from tkinter import messagebox\n                        messagebox.showinfo(self.text(\'更新\',\'Updates\'),self.text(\'暂无可用更新或发布服务暂不可用。\',\'No update available, or the release service is unavailable.\'),parent=self.app.root)\n            except queue.Empty:pass\n            self.app.root.after(200,self.poll)\n        def dialog(self,entries):\n            window=tk.Toplevel(self.app.root); window.title(self.text(\'发现更新版本\',\'New version available\')); window.transient(self.app.root)\n            ttk.Label(window,text=\'\\n\'.join(e[\'name\'] for e in entries),padding=16).pack()\n            row=ttk.Frame(window,padding=12); row.pack()\n            def download():\n                window.destroy(); self.busy=True\n                def work():\n                    staged=[]\n                    try:\n                        for entry in entries:staged.append(stage(entry,directory,script_path=script_path))\n                        self.events.put((\'ready\',staged,True))\n                    except Exception:\n                        for _,new,_ in staged:new.unlink(missing_ok=True)\n                        self.events.put((\'failed\',None,True))\n                threading.Thread(target=work,daemon=True).start()\n            def release():\n                import webbrowser\n                webbrowser.open(\'https://github.com/\'+REPOSITORY+\'/releases\')\n            for zh,en,command in [(\'自动更新\',\'Update automatically\',download),(\'打开发布页\',\'Open releases\',release),(\'暂不更新\',\'Later\',window.destroy)]:\n                ttk.Button(row,text=self.text(zh,en),command=command).pack(side=\'left\',padx=4)\n    def init(app,root):\n        original_init(app,root); state[\'app\']=app; app._auto_update=Controller(app)\n    def gui():\n        original_gui()\n        app=state[\'app\']\n        # board_shutdown sets this ONLY after all native-owner acknowledgements.\n        if app is not None and getattr(app,\'_shutdown_destroyed\',False):\n            for item in state[\'pending\']:\n                try:apply_staged(item)\n                except Exception:pass # Preserve old target and verified NEW for manual retry.\n    BoardApp.__init__=init; namespace[\'run_gui\']=gui\n', "board_auto_update", "exec"), _board_update_namespace)
